INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-7-integers','math','{"title":"Negative numbers","year":7,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-7-integers-1","topic":"oh-y711-v1-7-integers","prompt":"Calculate −5 + 9.","choices":["4","5","3","7"],"correct":0,"explanation":"Start at −5 and move 9 places right to reach 4.","hint":"Adding a positive number moves right on a number line.","passage":""},{"id":"oh-y711-v1-7-integers-2","topic":"oh-y711-v1-7-integers","prompt":"Calculate −6 + 11.","choices":["6","5","4","8"],"correct":1,"explanation":"Start at −6 and move 11 places right to reach 5.","hint":"Adding a positive number moves right on a number line.","passage":""},{"id":"oh-y711-v1-7-integers-3","topic":"oh-y711-v1-7-integers","prompt":"Calculate −7 + 13.","choices":["5","7","6","9"],"correct":2,"explanation":"Start at −7 and move 13 places right to reach 6.","hint":"Adding a positive number moves right on a number line.","passage":""},{"id":"oh-y711-v1-7-integers-4","topic":"oh-y711-v1-7-integers","prompt":"Calculate −8 + 15.","choices":["10","8","6","7"],"correct":3,"explanation":"Start at −8 and move 15 places right to reach 7.","hint":"Adding a positive number moves right on a number line.","passage":""},{"id":"oh-y711-v1-7-integers-5","topic":"oh-y711-v1-7-integers","prompt":"Calculate −9 + 17.","choices":["8","9","7","11"],"correct":0,"explanation":"Start at −9 and move 17 places right to reach 8.","hint":"Adding a positive number moves right on a number line.","passage":""},{"id":"oh-y711-v1-7-integers-6","topic":"oh-y711-v1-7-integers","prompt":"Calculate −10 + 19.","choices":["10","9","8","12"],"correct":1,"explanation":"Start at −10 and move 19 places right to reach 9.","hint":"Adding a positive number moves right on a number line.","passage":""},{"id":"oh-y711-v1-7-integers-7","topic":"oh-y711-v1-7-integers","prompt":"Calculate −11 + 21.","choices":["9","11","10","13"],"correct":2,"explanation":"Start at −11 and move 21 places right to reach 10.","hint":"Adding a positive number moves right on a number line.","passage":""},{"id":"oh-y711-v1-7-integers-8","topic":"oh-y711-v1-7-integers","prompt":"Calculate −12 + 23.","choices":["14","12","10","11"],"correct":3,"explanation":"Start at −12 and move 23 places right to reach 11.","hint":"Adding a positive number moves right on a number line.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-7-order','math','{"title":"Order of operations","year":7,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-7-order-1","topic":"oh-y711-v1-7-order","prompt":"Calculate 3 + 3 × 2.","choices":["9","10","8","12"],"correct":0,"explanation":"Multiply first: 3 × 2 = 6. Then add 3 to get 9.","hint":"Do multiplication before addition.","passage":""},{"id":"oh-y711-v1-7-order-2","topic":"oh-y711-v1-7-order","prompt":"Calculate 4 + 3 × 3.","choices":["14","13","12","16"],"correct":1,"explanation":"Multiply first: 3 × 3 = 9. Then add 4 to get 13.","hint":"Do multiplication before addition.","passage":""},{"id":"oh-y711-v1-7-order-3","topic":"oh-y711-v1-7-order","prompt":"Calculate 5 + 3 × 4.","choices":["16","18","17","20"],"correct":2,"explanation":"Multiply first: 3 × 4 = 12. Then add 5 to get 17.","hint":"Do multiplication before addition.","passage":""},{"id":"oh-y711-v1-7-order-4","topic":"oh-y711-v1-7-order","prompt":"Calculate 6 + 3 × 5.","choices":["24","22","20","21"],"correct":3,"explanation":"Multiply first: 3 × 5 = 15. Then add 6 to get 21.","hint":"Do multiplication before addition.","passage":""},{"id":"oh-y711-v1-7-order-5","topic":"oh-y711-v1-7-order","prompt":"Calculate 7 + 3 × 6.","choices":["25","26","24","28"],"correct":0,"explanation":"Multiply first: 3 × 6 = 18. Then add 7 to get 25.","hint":"Do multiplication before addition.","passage":""},{"id":"oh-y711-v1-7-order-6","topic":"oh-y711-v1-7-order","prompt":"Calculate 8 + 3 × 7.","choices":["30","29","28","32"],"correct":1,"explanation":"Multiply first: 3 × 7 = 21. Then add 8 to get 29.","hint":"Do multiplication before addition.","passage":""},{"id":"oh-y711-v1-7-order-7","topic":"oh-y711-v1-7-order","prompt":"Calculate 9 + 3 × 8.","choices":["32","34","33","36"],"correct":2,"explanation":"Multiply first: 3 × 8 = 24. Then add 9 to get 33.","hint":"Do multiplication before addition.","passage":""},{"id":"oh-y711-v1-7-order-8","topic":"oh-y711-v1-7-order","prompt":"Calculate 10 + 3 × 9.","choices":["40","38","36","37"],"correct":3,"explanation":"Multiply first: 3 × 9 = 27. Then add 10 to get 37.","hint":"Do multiplication before addition.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-7-fractions','math','{"title":"Adding fractions","year":7,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-7-fractions-1","topic":"oh-y711-v1-7-fractions","prompt":"Calculate 1/4 + 2/4. Give the simplest form.","choices":["3/4","1/2","1/4","1"],"correct":0,"explanation":"Add the numerators and keep the denominator: 3/4, simplified to 3/4.","hint":"The denominators already match.","passage":""},{"id":"oh-y711-v1-7-fractions-2","topic":"oh-y711-v1-7-fractions","prompt":"Calculate 1/5 + 2/5. Give the simplest form.","choices":["2/5","3/5","1/5","4/5"],"correct":1,"explanation":"Add the numerators and keep the denominator: 3/5, simplified to 3/5.","hint":"The denominators already match.","passage":""},{"id":"oh-y711-v1-7-fractions-3","topic":"oh-y711-v1-7-fractions","prompt":"Calculate 1/6 + 2/6. Give the simplest form.","choices":["1/6","1/3","1/2","2/3"],"correct":2,"explanation":"Add the numerators and keep the denominator: 3/6, simplified to 1/2.","hint":"The denominators already match.","passage":""},{"id":"oh-y711-v1-7-fractions-4","topic":"oh-y711-v1-7-fractions","prompt":"Calculate 1/7 + 2/7. Give the simplest form.","choices":["4/7","2/7","1/7","3/7"],"correct":3,"explanation":"Add the numerators and keep the denominator: 3/7, simplified to 3/7.","hint":"The denominators already match.","passage":""},{"id":"oh-y711-v1-7-fractions-5","topic":"oh-y711-v1-7-fractions","prompt":"Calculate 1/8 + 2/8. Give the simplest form.","choices":["3/8","1/4","1/8","1/2"],"correct":0,"explanation":"Add the numerators and keep the denominator: 3/8, simplified to 3/8.","hint":"The denominators already match.","passage":""},{"id":"oh-y711-v1-7-fractions-6","topic":"oh-y711-v1-7-fractions","prompt":"Calculate 1/9 + 2/9. Give the simplest form.","choices":["2/9","1/3","1/9","4/9"],"correct":1,"explanation":"Add the numerators and keep the denominator: 3/9, simplified to 1/3.","hint":"The denominators already match.","passage":""},{"id":"oh-y711-v1-7-fractions-7","topic":"oh-y711-v1-7-fractions","prompt":"Calculate 1/10 + 2/10. Give the simplest form.","choices":["1/10","1/5","3/10","2/5"],"correct":2,"explanation":"Add the numerators and keep the denominator: 3/10, simplified to 3/10.","hint":"The denominators already match.","passage":""},{"id":"oh-y711-v1-7-fractions-8","topic":"oh-y711-v1-7-fractions","prompt":"Calculate 1/11 + 2/11. Give the simplest form.","choices":["4/11","2/11","1/11","3/11"],"correct":3,"explanation":"Add the numerators and keep the denominator: 3/11, simplified to 3/11.","hint":"The denominators already match.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-7-decimals','math','{"title":"Multiplying decimals","year":7,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-7-decimals-1","topic":"oh-y711-v1-7-decimals","prompt":"Calculate 1.3 × 10.","choices":["13","14","12","16"],"correct":0,"explanation":"Each digit moves one place left in the place-value columns, giving 13.","hint":"Each digit becomes worth ten times as much.","passage":""},{"id":"oh-y711-v1-7-decimals-2","topic":"oh-y711-v1-7-decimals","prompt":"Calculate 2.3 × 10.","choices":["24","23","22","26"],"correct":1,"explanation":"Each digit moves one place left in the place-value columns, giving 23.","hint":"Each digit becomes worth ten times as much.","passage":""},{"id":"oh-y711-v1-7-decimals-3","topic":"oh-y711-v1-7-decimals","prompt":"Calculate 3.3 × 10.","choices":["32","34","33","36"],"correct":2,"explanation":"Each digit moves one place left in the place-value columns, giving 33.","hint":"Each digit becomes worth ten times as much.","passage":""},{"id":"oh-y711-v1-7-decimals-4","topic":"oh-y711-v1-7-decimals","prompt":"Calculate 4.3 × 10.","choices":["46","44","42","43"],"correct":3,"explanation":"Each digit moves one place left in the place-value columns, giving 43.","hint":"Each digit becomes worth ten times as much.","passage":""},{"id":"oh-y711-v1-7-decimals-5","topic":"oh-y711-v1-7-decimals","prompt":"Calculate 5.3 × 10.","choices":["53","54","52","56"],"correct":0,"explanation":"Each digit moves one place left in the place-value columns, giving 53.","hint":"Each digit becomes worth ten times as much.","passage":""},{"id":"oh-y711-v1-7-decimals-6","topic":"oh-y711-v1-7-decimals","prompt":"Calculate 6.3 × 10.","choices":["64","63","62","66"],"correct":1,"explanation":"Each digit moves one place left in the place-value columns, giving 63.","hint":"Each digit becomes worth ten times as much.","passage":""},{"id":"oh-y711-v1-7-decimals-7","topic":"oh-y711-v1-7-decimals","prompt":"Calculate 7.3 × 10.","choices":["72","74","73","76"],"correct":2,"explanation":"Each digit moves one place left in the place-value columns, giving 73.","hint":"Each digit becomes worth ten times as much.","passage":""},{"id":"oh-y711-v1-7-decimals-8","topic":"oh-y711-v1-7-decimals","prompt":"Calculate 8.3 × 10.","choices":["86","84","82","83"],"correct":3,"explanation":"Each digit moves one place left in the place-value columns, giving 83.","hint":"Each digit becomes worth ten times as much.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-7-percent','math','{"title":"Finding percentages","year":7,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-7-percent-1","topic":"oh-y711-v1-7-percent","prompt":"Find 10% of 50.","choices":["5","6","4","8"],"correct":0,"explanation":"10% is one tenth: 50 ÷ 10 = 5.","hint":"Divide the amount by 10.","passage":""},{"id":"oh-y711-v1-7-percent-2","topic":"oh-y711-v1-7-percent","prompt":"Find 10% of 80.","choices":["9","8","7","11"],"correct":1,"explanation":"10% is one tenth: 80 ÷ 10 = 8.","hint":"Divide the amount by 10.","passage":""},{"id":"oh-y711-v1-7-percent-3","topic":"oh-y711-v1-7-percent","prompt":"Find 10% of 110.","choices":["10","12","11","14"],"correct":2,"explanation":"10% is one tenth: 110 ÷ 10 = 11.","hint":"Divide the amount by 10.","passage":""},{"id":"oh-y711-v1-7-percent-4","topic":"oh-y711-v1-7-percent","prompt":"Find 10% of 140.","choices":["17","15","13","14"],"correct":3,"explanation":"10% is one tenth: 140 ÷ 10 = 14.","hint":"Divide the amount by 10.","passage":""},{"id":"oh-y711-v1-7-percent-5","topic":"oh-y711-v1-7-percent","prompt":"Find 10% of 170.","choices":["17","18","16","20"],"correct":0,"explanation":"10% is one tenth: 170 ÷ 10 = 17.","hint":"Divide the amount by 10.","passage":""},{"id":"oh-y711-v1-7-percent-6","topic":"oh-y711-v1-7-percent","prompt":"Find 10% of 200.","choices":["21","20","19","23"],"correct":1,"explanation":"10% is one tenth: 200 ÷ 10 = 20.","hint":"Divide the amount by 10.","passage":""},{"id":"oh-y711-v1-7-percent-7","topic":"oh-y711-v1-7-percent","prompt":"Find 10% of 230.","choices":["22","24","23","26"],"correct":2,"explanation":"10% is one tenth: 230 ÷ 10 = 23.","hint":"Divide the amount by 10.","passage":""},{"id":"oh-y711-v1-7-percent-8","topic":"oh-y711-v1-7-percent","prompt":"Find 10% of 260.","choices":["29","27","25","26"],"correct":3,"explanation":"10% is one tenth: 260 ÷ 10 = 26.","hint":"Divide the amount by 10.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-7-perimeter','math','{"title":"Rectangle perimeter","year":7,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-7-perimeter-1","topic":"oh-y711-v1-7-perimeter","prompt":"A rectangle is 6 cm long and 3 cm wide. Find its perimeter in cm.","choices":["18","19","17","21"],"correct":0,"explanation":"Perimeter = 2 × (6 + 3) = 18 cm.","hint":"Add all four sides.","passage":""},{"id":"oh-y711-v1-7-perimeter-2","topic":"oh-y711-v1-7-perimeter","prompt":"A rectangle is 7 cm long and 4 cm wide. Find its perimeter in cm.","choices":["23","22","21","25"],"correct":1,"explanation":"Perimeter = 2 × (7 + 4) = 22 cm.","hint":"Add all four sides.","passage":""},{"id":"oh-y711-v1-7-perimeter-3","topic":"oh-y711-v1-7-perimeter","prompt":"A rectangle is 8 cm long and 5 cm wide. Find its perimeter in cm.","choices":["25","27","26","29"],"correct":2,"explanation":"Perimeter = 2 × (8 + 5) = 26 cm.","hint":"Add all four sides.","passage":""},{"id":"oh-y711-v1-7-perimeter-4","topic":"oh-y711-v1-7-perimeter","prompt":"A rectangle is 9 cm long and 6 cm wide. Find its perimeter in cm.","choices":["33","31","29","30"],"correct":3,"explanation":"Perimeter = 2 × (9 + 6) = 30 cm.","hint":"Add all four sides.","passage":""},{"id":"oh-y711-v1-7-perimeter-5","topic":"oh-y711-v1-7-perimeter","prompt":"A rectangle is 10 cm long and 7 cm wide. Find its perimeter in cm.","choices":["34","35","33","37"],"correct":0,"explanation":"Perimeter = 2 × (10 + 7) = 34 cm.","hint":"Add all four sides.","passage":""},{"id":"oh-y711-v1-7-perimeter-6","topic":"oh-y711-v1-7-perimeter","prompt":"A rectangle is 11 cm long and 8 cm wide. Find its perimeter in cm.","choices":["39","38","37","41"],"correct":1,"explanation":"Perimeter = 2 × (11 + 8) = 38 cm.","hint":"Add all four sides.","passage":""},{"id":"oh-y711-v1-7-perimeter-7","topic":"oh-y711-v1-7-perimeter","prompt":"A rectangle is 12 cm long and 9 cm wide. Find its perimeter in cm.","choices":["41","43","42","45"],"correct":2,"explanation":"Perimeter = 2 × (12 + 9) = 42 cm.","hint":"Add all four sides.","passage":""},{"id":"oh-y711-v1-7-perimeter-8","topic":"oh-y711-v1-7-perimeter","prompt":"A rectangle is 13 cm long and 10 cm wide. Find its perimeter in cm.","choices":["49","47","45","46"],"correct":3,"explanation":"Perimeter = 2 × (13 + 10) = 46 cm.","hint":"Add all four sides.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-7-mean','math','{"title":"The mean average","year":7,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-7-mean-1","topic":"oh-y711-v1-7-mean","prompt":"Find the mean of 1, 3, 5, 7.","choices":["4","5","3","7"],"correct":0,"explanation":"The total is 16. Dividing by 4 gives 4.","hint":"Add the values, then divide by the number of values.","passage":""},{"id":"oh-y711-v1-7-mean-2","topic":"oh-y711-v1-7-mean","prompt":"Find the mean of 2, 4, 6, 8.","choices":["6","5","4","8"],"correct":1,"explanation":"The total is 20. Dividing by 4 gives 5.","hint":"Add the values, then divide by the number of values.","passage":""},{"id":"oh-y711-v1-7-mean-3","topic":"oh-y711-v1-7-mean","prompt":"Find the mean of 3, 5, 7, 9.","choices":["5","7","6","9"],"correct":2,"explanation":"The total is 24. Dividing by 4 gives 6.","hint":"Add the values, then divide by the number of values.","passage":""},{"id":"oh-y711-v1-7-mean-4","topic":"oh-y711-v1-7-mean","prompt":"Find the mean of 4, 6, 8, 10.","choices":["10","8","6","7"],"correct":3,"explanation":"The total is 28. Dividing by 4 gives 7.","hint":"Add the values, then divide by the number of values.","passage":""},{"id":"oh-y711-v1-7-mean-5","topic":"oh-y711-v1-7-mean","prompt":"Find the mean of 5, 7, 9, 11.","choices":["8","9","7","11"],"correct":0,"explanation":"The total is 32. Dividing by 4 gives 8.","hint":"Add the values, then divide by the number of values.","passage":""},{"id":"oh-y711-v1-7-mean-6","topic":"oh-y711-v1-7-mean","prompt":"Find the mean of 6, 8, 10, 12.","choices":["10","9","8","12"],"correct":1,"explanation":"The total is 36. Dividing by 4 gives 9.","hint":"Add the values, then divide by the number of values.","passage":""},{"id":"oh-y711-v1-7-mean-7","topic":"oh-y711-v1-7-mean","prompt":"Find the mean of 7, 9, 11, 13.","choices":["9","11","10","13"],"correct":2,"explanation":"The total is 40. Dividing by 4 gives 10.","hint":"Add the values, then divide by the number of values.","passage":""},{"id":"oh-y711-v1-7-mean-8","topic":"oh-y711-v1-7-mean","prompt":"Find the mean of 8, 10, 12, 14.","choices":["14","12","10","11"],"correct":3,"explanation":"The total is 44. Dividing by 4 gives 11.","hint":"Add the values, then divide by the number of values.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-8-ratio','math','{"title":"Sharing in a ratio","year":8,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-8-ratio-1","topic":"oh-y711-v1-8-ratio","prompt":"£20 is shared between Ali and Bea in the ratio 2:3. How many pounds does Bea receive?","choices":["12","13","11","15"],"correct":0,"explanation":"There are 5 parts. Each is £4, so Bea gets 3 × £4 = £12.","hint":"Find the value of one part first.","passage":""},{"id":"oh-y711-v1-8-ratio-2","topic":"oh-y711-v1-8-ratio","prompt":"£25 is shared between Ali and Bea in the ratio 2:3. How many pounds does Bea receive?","choices":["16","15","14","18"],"correct":1,"explanation":"There are 5 parts. Each is £5, so Bea gets 3 × £5 = £15.","hint":"Find the value of one part first.","passage":""},{"id":"oh-y711-v1-8-ratio-3","topic":"oh-y711-v1-8-ratio","prompt":"£30 is shared between Ali and Bea in the ratio 2:3. How many pounds does Bea receive?","choices":["17","19","18","21"],"correct":2,"explanation":"There are 5 parts. Each is £6, so Bea gets 3 × £6 = £18.","hint":"Find the value of one part first.","passage":""},{"id":"oh-y711-v1-8-ratio-4","topic":"oh-y711-v1-8-ratio","prompt":"£35 is shared between Ali and Bea in the ratio 2:3. How many pounds does Bea receive?","choices":["24","22","20","21"],"correct":3,"explanation":"There are 5 parts. Each is £7, so Bea gets 3 × £7 = £21.","hint":"Find the value of one part first.","passage":""},{"id":"oh-y711-v1-8-ratio-5","topic":"oh-y711-v1-8-ratio","prompt":"£40 is shared between Ali and Bea in the ratio 2:3. How many pounds does Bea receive?","choices":["24","25","23","27"],"correct":0,"explanation":"There are 5 parts. Each is £8, so Bea gets 3 × £8 = £24.","hint":"Find the value of one part first.","passage":""},{"id":"oh-y711-v1-8-ratio-6","topic":"oh-y711-v1-8-ratio","prompt":"£45 is shared between Ali and Bea in the ratio 2:3. How many pounds does Bea receive?","choices":["28","27","26","30"],"correct":1,"explanation":"There are 5 parts. Each is £9, so Bea gets 3 × £9 = £27.","hint":"Find the value of one part first.","passage":""},{"id":"oh-y711-v1-8-ratio-7","topic":"oh-y711-v1-8-ratio","prompt":"£50 is shared between Ali and Bea in the ratio 2:3. How many pounds does Bea receive?","choices":["29","31","30","33"],"correct":2,"explanation":"There are 5 parts. Each is £10, so Bea gets 3 × £10 = £30.","hint":"Find the value of one part first.","passage":""},{"id":"oh-y711-v1-8-ratio-8","topic":"oh-y711-v1-8-ratio","prompt":"£55 is shared between Ali and Bea in the ratio 2:3. How many pounds does Bea receive?","choices":["36","34","32","33"],"correct":3,"explanation":"There are 5 parts. Each is £11, so Bea gets 3 × £11 = £33.","hint":"Find the value of one part first.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-8-equations','math','{"title":"Two-step equations","year":8,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-8-equations-1","topic":"oh-y711-v1-8-equations","prompt":"Solve 3x + 3 = 12.","choices":["3","4","2","6"],"correct":0,"explanation":"Subtract 3: 3x = 9. Divide by 3: x = 3.","hint":"Undo the addition, then the multiplication.","passage":""},{"id":"oh-y711-v1-8-equations-2","topic":"oh-y711-v1-8-equations","prompt":"Solve 3x + 4 = 16.","choices":["5","4","3","7"],"correct":1,"explanation":"Subtract 4: 3x = 12. Divide by 3: x = 4.","hint":"Undo the addition, then the multiplication.","passage":""},{"id":"oh-y711-v1-8-equations-3","topic":"oh-y711-v1-8-equations","prompt":"Solve 3x + 5 = 20.","choices":["4","6","5","8"],"correct":2,"explanation":"Subtract 5: 3x = 15. Divide by 3: x = 5.","hint":"Undo the addition, then the multiplication.","passage":""},{"id":"oh-y711-v1-8-equations-4","topic":"oh-y711-v1-8-equations","prompt":"Solve 3x + 6 = 24.","choices":["9","7","5","6"],"correct":3,"explanation":"Subtract 6: 3x = 18. Divide by 3: x = 6.","hint":"Undo the addition, then the multiplication.","passage":""},{"id":"oh-y711-v1-8-equations-5","topic":"oh-y711-v1-8-equations","prompt":"Solve 3x + 7 = 28.","choices":["7","8","6","10"],"correct":0,"explanation":"Subtract 7: 3x = 21. Divide by 3: x = 7.","hint":"Undo the addition, then the multiplication.","passage":""},{"id":"oh-y711-v1-8-equations-6","topic":"oh-y711-v1-8-equations","prompt":"Solve 3x + 8 = 32.","choices":["9","8","7","11"],"correct":1,"explanation":"Subtract 8: 3x = 24. Divide by 3: x = 8.","hint":"Undo the addition, then the multiplication.","passage":""},{"id":"oh-y711-v1-8-equations-7","topic":"oh-y711-v1-8-equations","prompt":"Solve 3x + 9 = 36.","choices":["8","10","9","12"],"correct":2,"explanation":"Subtract 9: 3x = 27. Divide by 3: x = 9.","hint":"Undo the addition, then the multiplication.","passage":""},{"id":"oh-y711-v1-8-equations-8","topic":"oh-y711-v1-8-equations","prompt":"Solve 3x + 10 = 40.","choices":["13","11","9","10"],"correct":3,"explanation":"Subtract 10: 3x = 30. Divide by 3: x = 10.","hint":"Undo the addition, then the multiplication.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-8-sequences','math','{"title":"Linear sequences","year":8,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-8-sequences-1","topic":"oh-y711-v1-8-sequences","prompt":"The nth term is 3n + 3. What is the 5th term?","choices":["18","19","17","21"],"correct":0,"explanation":"Substitute n = 5: 3 × 5 + 3 = 18.","hint":"n means the position of a term.","passage":""},{"id":"oh-y711-v1-8-sequences-2","topic":"oh-y711-v1-8-sequences","prompt":"The nth term is 4n + 3. What is the 5th term?","choices":["24","23","22","26"],"correct":1,"explanation":"Substitute n = 5: 4 × 5 + 3 = 23.","hint":"n means the position of a term.","passage":""},{"id":"oh-y711-v1-8-sequences-3","topic":"oh-y711-v1-8-sequences","prompt":"The nth term is 5n + 3. What is the 5th term?","choices":["27","29","28","31"],"correct":2,"explanation":"Substitute n = 5: 5 × 5 + 3 = 28.","hint":"n means the position of a term.","passage":""},{"id":"oh-y711-v1-8-sequences-4","topic":"oh-y711-v1-8-sequences","prompt":"The nth term is 6n + 3. What is the 5th term?","choices":["36","34","32","33"],"correct":3,"explanation":"Substitute n = 5: 6 × 5 + 3 = 33.","hint":"n means the position of a term.","passage":""},{"id":"oh-y711-v1-8-sequences-5","topic":"oh-y711-v1-8-sequences","prompt":"The nth term is 7n + 3. What is the 5th term?","choices":["38","39","37","41"],"correct":0,"explanation":"Substitute n = 5: 7 × 5 + 3 = 38.","hint":"n means the position of a term.","passage":""},{"id":"oh-y711-v1-8-sequences-6","topic":"oh-y711-v1-8-sequences","prompt":"The nth term is 8n + 3. What is the 5th term?","choices":["44","43","42","46"],"correct":1,"explanation":"Substitute n = 5: 8 × 5 + 3 = 43.","hint":"n means the position of a term.","passage":""},{"id":"oh-y711-v1-8-sequences-7","topic":"oh-y711-v1-8-sequences","prompt":"The nth term is 9n + 3. What is the 5th term?","choices":["47","49","48","51"],"correct":2,"explanation":"Substitute n = 5: 9 × 5 + 3 = 48.","hint":"n means the position of a term.","passage":""},{"id":"oh-y711-v1-8-sequences-8","topic":"oh-y711-v1-8-sequences","prompt":"The nth term is 10n + 3. What is the 5th term?","choices":["56","54","52","53"],"correct":3,"explanation":"Substitute n = 5: 10 × 5 + 3 = 53.","hint":"n means the position of a term.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-8-angles','math','{"title":"Angles in triangles","year":8,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-8-angles-1","topic":"oh-y711-v1-8-angles","prompt":"Two angles in a triangle are 31° and 62°. Find the third angle in degrees.","choices":["87","88","86","90"],"correct":0,"explanation":"180 − 31 − 62 = 87°.","hint":"The angles in a triangle total 180°.","passage":""},{"id":"oh-y711-v1-8-angles-2","topic":"oh-y711-v1-8-angles","prompt":"Two angles in a triangle are 32° and 64°. Find the third angle in degrees.","choices":["85","84","83","87"],"correct":1,"explanation":"180 − 32 − 64 = 84°.","hint":"The angles in a triangle total 180°.","passage":""},{"id":"oh-y711-v1-8-angles-3","topic":"oh-y711-v1-8-angles","prompt":"Two angles in a triangle are 33° and 66°. Find the third angle in degrees.","choices":["80","82","81","84"],"correct":2,"explanation":"180 − 33 − 66 = 81°.","hint":"The angles in a triangle total 180°.","passage":""},{"id":"oh-y711-v1-8-angles-4","topic":"oh-y711-v1-8-angles","prompt":"Two angles in a triangle are 34° and 68°. Find the third angle in degrees.","choices":["81","79","77","78"],"correct":3,"explanation":"180 − 34 − 68 = 78°.","hint":"The angles in a triangle total 180°.","passage":""},{"id":"oh-y711-v1-8-angles-5","topic":"oh-y711-v1-8-angles","prompt":"Two angles in a triangle are 35° and 70°. Find the third angle in degrees.","choices":["75","76","74","78"],"correct":0,"explanation":"180 − 35 − 70 = 75°.","hint":"The angles in a triangle total 180°.","passage":""},{"id":"oh-y711-v1-8-angles-6","topic":"oh-y711-v1-8-angles","prompt":"Two angles in a triangle are 36° and 72°. Find the third angle in degrees.","choices":["73","72","71","75"],"correct":1,"explanation":"180 − 36 − 72 = 72°.","hint":"The angles in a triangle total 180°.","passage":""},{"id":"oh-y711-v1-8-angles-7","topic":"oh-y711-v1-8-angles","prompt":"Two angles in a triangle are 37° and 74°. Find the third angle in degrees.","choices":["68","70","69","72"],"correct":2,"explanation":"180 − 37 − 74 = 69°.","hint":"The angles in a triangle total 180°.","passage":""},{"id":"oh-y711-v1-8-angles-8","topic":"oh-y711-v1-8-angles","prompt":"Two angles in a triangle are 38° and 76°. Find the third angle in degrees.","choices":["69","67","65","66"],"correct":3,"explanation":"180 − 38 − 76 = 66°.","hint":"The angles in a triangle total 180°.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-8-area','math','{"title":"Area of a triangle","year":8,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-8-area-1","topic":"oh-y711-v1-8-area","prompt":"A triangle has base 6 cm and perpendicular height 4 cm. Find its area in cm².","choices":["12","13","11","15"],"correct":0,"explanation":"Area = ½ × 6 × 4 = 12 cm².","hint":"Use half × base × perpendicular height.","passage":""},{"id":"oh-y711-v1-8-area-2","topic":"oh-y711-v1-8-area","prompt":"A triangle has base 8 cm and perpendicular height 5 cm. Find its area in cm².","choices":["21","20","19","23"],"correct":1,"explanation":"Area = ½ × 8 × 5 = 20 cm².","hint":"Use half × base × perpendicular height.","passage":""},{"id":"oh-y711-v1-8-area-3","topic":"oh-y711-v1-8-area","prompt":"A triangle has base 10 cm and perpendicular height 6 cm. Find its area in cm².","choices":["29","31","30","33"],"correct":2,"explanation":"Area = ½ × 10 × 6 = 30 cm².","hint":"Use half × base × perpendicular height.","passage":""},{"id":"oh-y711-v1-8-area-4","topic":"oh-y711-v1-8-area","prompt":"A triangle has base 12 cm and perpendicular height 7 cm. Find its area in cm².","choices":["45","43","41","42"],"correct":3,"explanation":"Area = ½ × 12 × 7 = 42 cm².","hint":"Use half × base × perpendicular height.","passage":""},{"id":"oh-y711-v1-8-area-5","topic":"oh-y711-v1-8-area","prompt":"A triangle has base 14 cm and perpendicular height 8 cm. Find its area in cm².","choices":["56","57","55","59"],"correct":0,"explanation":"Area = ½ × 14 × 8 = 56 cm².","hint":"Use half × base × perpendicular height.","passage":""},{"id":"oh-y711-v1-8-area-6","topic":"oh-y711-v1-8-area","prompt":"A triangle has base 16 cm and perpendicular height 9 cm. Find its area in cm².","choices":["73","72","71","75"],"correct":1,"explanation":"Area = ½ × 16 × 9 = 72 cm².","hint":"Use half × base × perpendicular height.","passage":""},{"id":"oh-y711-v1-8-area-7","topic":"oh-y711-v1-8-area","prompt":"A triangle has base 18 cm and perpendicular height 10 cm. Find its area in cm².","choices":["89","91","90","93"],"correct":2,"explanation":"Area = ½ × 18 × 10 = 90 cm².","hint":"Use half × base × perpendicular height.","passage":""},{"id":"oh-y711-v1-8-area-8","topic":"oh-y711-v1-8-area","prompt":"A triangle has base 20 cm and perpendicular height 11 cm. Find its area in cm².","choices":["113","111","109","110"],"correct":3,"explanation":"Area = ½ × 20 × 11 = 110 cm².","hint":"Use half × base × perpendicular height.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-8-probability','math','{"title":"Simple probability","year":8,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-8-probability-1","topic":"oh-y711-v1-8-probability","prompt":"A bag contains 1 red and 3 blue counters. One is chosen at random. What is the probability of red?","choices":["1/4","3/4","0","1"],"correct":0,"explanation":"There are 4 counters and 1 are red, so the probability is 1/4.","hint":"Divide favourable outcomes by total equally likely outcomes.","passage":""},{"id":"oh-y711-v1-8-probability-2","topic":"oh-y711-v1-8-probability","prompt":"A bag contains 2 red and 4 blue counters. One is chosen at random. What is the probability of red?","choices":["2/3","1/3","0","1"],"correct":1,"explanation":"There are 6 counters and 2 are red, so the probability is 1/3.","hint":"Divide favourable outcomes by total equally likely outcomes.","passage":""},{"id":"oh-y711-v1-8-probability-3","topic":"oh-y711-v1-8-probability","prompt":"A bag contains 3 red and 5 blue counters. One is chosen at random. What is the probability of red?","choices":["0","5/8","3/8","1"],"correct":2,"explanation":"There are 8 counters and 3 are red, so the probability is 3/8.","hint":"Divide favourable outcomes by total equally likely outcomes.","passage":""},{"id":"oh-y711-v1-8-probability-4","topic":"oh-y711-v1-8-probability","prompt":"A bag contains 4 red and 6 blue counters. One is chosen at random. What is the probability of red?","choices":["1","3/5","0","2/5"],"correct":3,"explanation":"There are 10 counters and 4 are red, so the probability is 2/5.","hint":"Divide favourable outcomes by total equally likely outcomes.","passage":""},{"id":"oh-y711-v1-8-probability-5","topic":"oh-y711-v1-8-probability","prompt":"A bag contains 5 red and 7 blue counters. One is chosen at random. What is the probability of red?","choices":["5/12","7/12","0","1"],"correct":0,"explanation":"There are 12 counters and 5 are red, so the probability is 5/12.","hint":"Divide favourable outcomes by total equally likely outcomes.","passage":""},{"id":"oh-y711-v1-8-probability-6","topic":"oh-y711-v1-8-probability","prompt":"A bag contains 6 red and 8 blue counters. One is chosen at random. What is the probability of red?","choices":["4/7","3/7","0","1"],"correct":1,"explanation":"There are 14 counters and 6 are red, so the probability is 3/7.","hint":"Divide favourable outcomes by total equally likely outcomes.","passage":""},{"id":"oh-y711-v1-8-probability-7","topic":"oh-y711-v1-8-probability","prompt":"A bag contains 7 red and 9 blue counters. One is chosen at random. What is the probability of red?","choices":["0","9/16","7/16","1"],"correct":2,"explanation":"There are 16 counters and 7 are red, so the probability is 7/16.","hint":"Divide favourable outcomes by total equally likely outcomes.","passage":""},{"id":"oh-y711-v1-8-probability-8","topic":"oh-y711-v1-8-probability","prompt":"A bag contains 8 red and 10 blue counters. One is chosen at random. What is the probability of red?","choices":["1","5/9","0","4/9"],"correct":3,"explanation":"There are 18 counters and 8 are red, so the probability is 4/9.","hint":"Divide favourable outcomes by total equally likely outcomes.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-8-coordinates','math','{"title":"Straight-line coordinates","year":8,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-8-coordinates-1","topic":"oh-y711-v1-8-coordinates","prompt":"A line has equation y = 2x + 1. What is y when x = 2?","choices":["5","6","4","8"],"correct":0,"explanation":"y = 2 × 2 + 1 = 5.","hint":"Substitute the x value into the equation.","passage":""},{"id":"oh-y711-v1-8-coordinates-2","topic":"oh-y711-v1-8-coordinates","prompt":"A line has equation y = 2x + 2. What is y when x = 3?","choices":["9","8","7","11"],"correct":1,"explanation":"y = 2 × 3 + 2 = 8.","hint":"Substitute the x value into the equation.","passage":""},{"id":"oh-y711-v1-8-coordinates-3","topic":"oh-y711-v1-8-coordinates","prompt":"A line has equation y = 2x + 3. What is y when x = 4?","choices":["10","12","11","14"],"correct":2,"explanation":"y = 2 × 4 + 3 = 11.","hint":"Substitute the x value into the equation.","passage":""},{"id":"oh-y711-v1-8-coordinates-4","topic":"oh-y711-v1-8-coordinates","prompt":"A line has equation y = 2x + 4. What is y when x = 5?","choices":["17","15","13","14"],"correct":3,"explanation":"y = 2 × 5 + 4 = 14.","hint":"Substitute the x value into the equation.","passage":""},{"id":"oh-y711-v1-8-coordinates-5","topic":"oh-y711-v1-8-coordinates","prompt":"A line has equation y = 2x + 5. What is y when x = 6?","choices":["17","18","16","20"],"correct":0,"explanation":"y = 2 × 6 + 5 = 17.","hint":"Substitute the x value into the equation.","passage":""},{"id":"oh-y711-v1-8-coordinates-6","topic":"oh-y711-v1-8-coordinates","prompt":"A line has equation y = 2x + 6. What is y when x = 7?","choices":["21","20","19","23"],"correct":1,"explanation":"y = 2 × 7 + 6 = 20.","hint":"Substitute the x value into the equation.","passage":""},{"id":"oh-y711-v1-8-coordinates-7","topic":"oh-y711-v1-8-coordinates","prompt":"A line has equation y = 2x + 7. What is y when x = 8?","choices":["22","24","23","26"],"correct":2,"explanation":"y = 2 × 8 + 7 = 23.","hint":"Substitute the x value into the equation.","passage":""},{"id":"oh-y711-v1-8-coordinates-8","topic":"oh-y711-v1-8-coordinates","prompt":"A line has equation y = 2x + 8. What is y when x = 9?","choices":["29","27","25","26"],"correct":3,"explanation":"y = 2 × 9 + 8 = 26.","hint":"Substitute the x value into the equation.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-9-expanding','math','{"title":"Expanding brackets","year":9,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-9-expanding-1","topic":"oh-y711-v1-9-expanding","prompt":"Expand 3(x + 2).","choices":["3x + 6","3x + 2","x + 6","4x + 6"],"correct":0,"explanation":"Multiply both x and 2 by 3.","hint":"The outside number multiplies every term inside.","passage":""},{"id":"oh-y711-v1-9-expanding-2","topic":"oh-y711-v1-9-expanding","prompt":"Expand 4(x + 3).","choices":["4x + 3","4x + 12","x + 12","5x + 12"],"correct":1,"explanation":"Multiply both x and 3 by 4.","hint":"The outside number multiplies every term inside.","passage":""},{"id":"oh-y711-v1-9-expanding-3","topic":"oh-y711-v1-9-expanding","prompt":"Expand 5(x + 4).","choices":["x + 20","5x + 4","5x + 20","6x + 20"],"correct":2,"explanation":"Multiply both x and 4 by 5.","hint":"The outside number multiplies every term inside.","passage":""},{"id":"oh-y711-v1-9-expanding-4","topic":"oh-y711-v1-9-expanding","prompt":"Expand 6(x + 5).","choices":["7x + 30","6x + 5","x + 30","6x + 30"],"correct":3,"explanation":"Multiply both x and 5 by 6.","hint":"The outside number multiplies every term inside.","passage":""},{"id":"oh-y711-v1-9-expanding-5","topic":"oh-y711-v1-9-expanding","prompt":"Expand 7(x + 6).","choices":["7x + 42","7x + 6","x + 42","8x + 42"],"correct":0,"explanation":"Multiply both x and 6 by 7.","hint":"The outside number multiplies every term inside.","passage":""},{"id":"oh-y711-v1-9-expanding-6","topic":"oh-y711-v1-9-expanding","prompt":"Expand 8(x + 7).","choices":["8x + 7","8x + 56","x + 56","9x + 56"],"correct":1,"explanation":"Multiply both x and 7 by 8.","hint":"The outside number multiplies every term inside.","passage":""},{"id":"oh-y711-v1-9-expanding-7","topic":"oh-y711-v1-9-expanding","prompt":"Expand 9(x + 8).","choices":["x + 72","9x + 8","9x + 72","10x + 72"],"correct":2,"explanation":"Multiply both x and 8 by 9.","hint":"The outside number multiplies every term inside.","passage":""},{"id":"oh-y711-v1-9-expanding-8","topic":"oh-y711-v1-9-expanding","prompt":"Expand 10(x + 9).","choices":["11x + 90","10x + 9","x + 90","10x + 90"],"correct":3,"explanation":"Multiply both x and 9 by 10.","hint":"The outside number multiplies every term inside.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-9-powers','math','{"title":"Index laws","year":9,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-9-powers-1","topic":"oh-y711-v1-9-powers","prompt":"Simplify x^2 × x^4.","choices":["x^6","x^5","x^7","x^2"],"correct":0,"explanation":"Add the indices: 2 + 4 = 6.","hint":"When multiplying powers of the same base, add their indices.","passage":""},{"id":"oh-y711-v1-9-powers-2","topic":"oh-y711-v1-9-powers","prompt":"Simplify x^3 × x^5.","choices":["x^7","x^8","x^9","x^2"],"correct":1,"explanation":"Add the indices: 3 + 5 = 8.","hint":"When multiplying powers of the same base, add their indices.","passage":""},{"id":"oh-y711-v1-9-powers-3","topic":"oh-y711-v1-9-powers","prompt":"Simplify x^4 × x^6.","choices":["x^11","x^9","x^10","x^2"],"correct":2,"explanation":"Add the indices: 4 + 6 = 10.","hint":"When multiplying powers of the same base, add their indices.","passage":""},{"id":"oh-y711-v1-9-powers-4","topic":"oh-y711-v1-9-powers","prompt":"Simplify x^5 × x^7.","choices":["x^2","x^11","x^13","x^12"],"correct":3,"explanation":"Add the indices: 5 + 7 = 12.","hint":"When multiplying powers of the same base, add their indices.","passage":""},{"id":"oh-y711-v1-9-powers-5","topic":"oh-y711-v1-9-powers","prompt":"Simplify x^6 × x^8.","choices":["x^14","x^13","x^15","x^2"],"correct":0,"explanation":"Add the indices: 6 + 8 = 14.","hint":"When multiplying powers of the same base, add their indices.","passage":""},{"id":"oh-y711-v1-9-powers-6","topic":"oh-y711-v1-9-powers","prompt":"Simplify x^7 × x^9.","choices":["x^15","x^16","x^17","x^2"],"correct":1,"explanation":"Add the indices: 7 + 9 = 16.","hint":"When multiplying powers of the same base, add their indices.","passage":""},{"id":"oh-y711-v1-9-powers-7","topic":"oh-y711-v1-9-powers","prompt":"Simplify x^8 × x^10.","choices":["x^19","x^17","x^18","x^2"],"correct":2,"explanation":"Add the indices: 8 + 10 = 18.","hint":"When multiplying powers of the same base, add their indices.","passage":""},{"id":"oh-y711-v1-9-powers-8","topic":"oh-y711-v1-9-powers","prompt":"Simplify x^9 × x^11.","choices":["x^2","x^19","x^21","x^20"],"correct":3,"explanation":"Add the indices: 9 + 11 = 20.","hint":"When multiplying powers of the same base, add their indices.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-9-standard','math','{"title":"Standard form","year":9,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-9-standard-1","topic":"oh-y711-v1-9-standard","prompt":"Write 12000 in standard form.","choices":["1.2 × 10^4","1.2 × 10^3","1.2 × 10^5","1.2 × 10^2"],"correct":0,"explanation":"1.2 × 10,000 = 12000.","hint":"The first factor must be at least 1 and less than 10.","passage":""},{"id":"oh-y711-v1-9-standard-2","topic":"oh-y711-v1-9-standard","prompt":"Write 22000 in standard form.","choices":["2.2 × 10^3","2.2 × 10^4","2.2 × 10^5","2.2 × 10^2"],"correct":1,"explanation":"2.2 × 10,000 = 22000.","hint":"The first factor must be at least 1 and less than 10.","passage":""},{"id":"oh-y711-v1-9-standard-3","topic":"oh-y711-v1-9-standard","prompt":"Write 32000 in standard form.","choices":["3.2 × 10^5","3.2 × 10^3","3.2 × 10^4","3.2 × 10^2"],"correct":2,"explanation":"3.2 × 10,000 = 32000.","hint":"The first factor must be at least 1 and less than 10.","passage":""},{"id":"oh-y711-v1-9-standard-4","topic":"oh-y711-v1-9-standard","prompt":"Write 42000 in standard form.","choices":["4.2 × 10^2","4.2 × 10^3","4.2 × 10^5","4.2 × 10^4"],"correct":3,"explanation":"4.2 × 10,000 = 42000.","hint":"The first factor must be at least 1 and less than 10.","passage":""},{"id":"oh-y711-v1-9-standard-5","topic":"oh-y711-v1-9-standard","prompt":"Write 52000 in standard form.","choices":["5.2 × 10^4","5.2 × 10^3","5.2 × 10^5","5.2 × 10^2"],"correct":0,"explanation":"5.2 × 10,000 = 52000.","hint":"The first factor must be at least 1 and less than 10.","passage":""},{"id":"oh-y711-v1-9-standard-6","topic":"oh-y711-v1-9-standard","prompt":"Write 62000 in standard form.","choices":["6.2 × 10^3","6.2 × 10^4","6.2 × 10^5","6.2 × 10^2"],"correct":1,"explanation":"6.2 × 10,000 = 62000.","hint":"The first factor must be at least 1 and less than 10.","passage":""},{"id":"oh-y711-v1-9-standard-7","topic":"oh-y711-v1-9-standard","prompt":"Write 72000 in standard form.","choices":["7.2 × 10^5","7.2 × 10^3","7.2 × 10^4","7.2 × 10^2"],"correct":2,"explanation":"7.2 × 10,000 = 72000.","hint":"The first factor must be at least 1 and less than 10.","passage":""},{"id":"oh-y711-v1-9-standard-8","topic":"oh-y711-v1-9-standard","prompt":"Write 82000 in standard form.","choices":["8.2 × 10^2","8.2 × 10^3","8.2 × 10^5","8.2 × 10^4"],"correct":3,"explanation":"8.2 × 10,000 = 82000.","hint":"The first factor must be at least 1 and less than 10.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-9-pythagoras','math','{"title":"Pythagoras’ theorem","year":9,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-9-pythagoras-1","topic":"oh-y711-v1-9-pythagoras","prompt":"The perpendicular sides of a right-angled triangle are 3 cm and 4 cm. Find the hypotenuse in cm.","choices":["5","6","4","8"],"correct":0,"explanation":"c² = 3² + 4² = 25, so c = 5 cm.","hint":"Square the shorter sides, add, then take the square root.","passage":""},{"id":"oh-y711-v1-9-pythagoras-2","topic":"oh-y711-v1-9-pythagoras","prompt":"The perpendicular sides of a right-angled triangle are 6 cm and 8 cm. Find the hypotenuse in cm.","choices":["11","10","9","13"],"correct":1,"explanation":"c² = 6² + 8² = 100, so c = 10 cm.","hint":"Square the shorter sides, add, then take the square root.","passage":""},{"id":"oh-y711-v1-9-pythagoras-3","topic":"oh-y711-v1-9-pythagoras","prompt":"The perpendicular sides of a right-angled triangle are 9 cm and 12 cm. Find the hypotenuse in cm.","choices":["14","16","15","18"],"correct":2,"explanation":"c² = 9² + 12² = 225, so c = 15 cm.","hint":"Square the shorter sides, add, then take the square root.","passage":""},{"id":"oh-y711-v1-9-pythagoras-4","topic":"oh-y711-v1-9-pythagoras","prompt":"The perpendicular sides of a right-angled triangle are 12 cm and 16 cm. Find the hypotenuse in cm.","choices":["23","21","19","20"],"correct":3,"explanation":"c² = 12² + 16² = 400, so c = 20 cm.","hint":"Square the shorter sides, add, then take the square root.","passage":""},{"id":"oh-y711-v1-9-pythagoras-5","topic":"oh-y711-v1-9-pythagoras","prompt":"The perpendicular sides of a right-angled triangle are 15 cm and 20 cm. Find the hypotenuse in cm.","choices":["25","26","24","28"],"correct":0,"explanation":"c² = 15² + 20² = 625, so c = 25 cm.","hint":"Square the shorter sides, add, then take the square root.","passage":""},{"id":"oh-y711-v1-9-pythagoras-6","topic":"oh-y711-v1-9-pythagoras","prompt":"The perpendicular sides of a right-angled triangle are 18 cm and 24 cm. Find the hypotenuse in cm.","choices":["31","30","29","33"],"correct":1,"explanation":"c² = 18² + 24² = 900, so c = 30 cm.","hint":"Square the shorter sides, add, then take the square root.","passage":""},{"id":"oh-y711-v1-9-pythagoras-7","topic":"oh-y711-v1-9-pythagoras","prompt":"The perpendicular sides of a right-angled triangle are 21 cm and 28 cm. Find the hypotenuse in cm.","choices":["34","36","35","38"],"correct":2,"explanation":"c² = 21² + 28² = 1225, so c = 35 cm.","hint":"Square the shorter sides, add, then take the square root.","passage":""},{"id":"oh-y711-v1-9-pythagoras-8","topic":"oh-y711-v1-9-pythagoras","prompt":"The perpendicular sides of a right-angled triangle are 24 cm and 32 cm. Find the hypotenuse in cm.","choices":["43","41","39","40"],"correct":3,"explanation":"c² = 24² + 32² = 1600, so c = 40 cm.","hint":"Square the shorter sides, add, then take the square root.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-9-percent-change','math','{"title":"Percentage increase","year":9,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-9-percent-change-1","topic":"oh-y711-v1-9-percent-change","prompt":"A £40 item increases by 15%. What is the new price in pounds?","choices":["46","47","45","49"],"correct":0,"explanation":"Multiply by 1.15: 40 × 1.15 = 46.","hint":"The new price is 115% of the original.","passage":""},{"id":"oh-y711-v1-9-percent-change-2","topic":"oh-y711-v1-9-percent-change","prompt":"A £60 item increases by 15%. What is the new price in pounds?","choices":["70","69","68","72"],"correct":1,"explanation":"Multiply by 1.15: 60 × 1.15 = 69.","hint":"The new price is 115% of the original.","passage":""},{"id":"oh-y711-v1-9-percent-change-3","topic":"oh-y711-v1-9-percent-change","prompt":"A £80 item increases by 15%. What is the new price in pounds?","choices":["91","93","92","95"],"correct":2,"explanation":"Multiply by 1.15: 80 × 1.15 = 92.","hint":"The new price is 115% of the original.","passage":""},{"id":"oh-y711-v1-9-percent-change-4","topic":"oh-y711-v1-9-percent-change","prompt":"A £100 item increases by 15%. What is the new price in pounds?","choices":["118","116","114","115"],"correct":3,"explanation":"Multiply by 1.15: 100 × 1.15 = 115.","hint":"The new price is 115% of the original.","passage":""},{"id":"oh-y711-v1-9-percent-change-5","topic":"oh-y711-v1-9-percent-change","prompt":"A £120 item increases by 15%. What is the new price in pounds?","choices":["138","139","137","141"],"correct":0,"explanation":"Multiply by 1.15: 120 × 1.15 = 138.","hint":"The new price is 115% of the original.","passage":""},{"id":"oh-y711-v1-9-percent-change-6","topic":"oh-y711-v1-9-percent-change","prompt":"A £140 item increases by 15%. What is the new price in pounds?","choices":["162","161","160","164"],"correct":1,"explanation":"Multiply by 1.15: 140 × 1.15 = 161.","hint":"The new price is 115% of the original.","passage":""},{"id":"oh-y711-v1-9-percent-change-7","topic":"oh-y711-v1-9-percent-change","prompt":"A £160 item increases by 15%. What is the new price in pounds?","choices":["183","185","184","187"],"correct":2,"explanation":"Multiply by 1.15: 160 × 1.15 = 184.","hint":"The new price is 115% of the original.","passage":""},{"id":"oh-y711-v1-9-percent-change-8","topic":"oh-y711-v1-9-percent-change","prompt":"A £180 item increases by 15%. What is the new price in pounds?","choices":["210","208","206","207"],"correct":3,"explanation":"Multiply by 1.15: 180 × 1.15 = 207.","hint":"The new price is 115% of the original.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-9-volume','math','{"title":"Volume of a cuboid","year":9,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-9-volume-1","topic":"oh-y711-v1-9-volume","prompt":"A cuboid measures 3 cm by 3 cm by 4 cm. Find its volume in cm³.","choices":["36","37","35","39"],"correct":0,"explanation":"Volume = 3 × 3 × 4 = 36 cm³.","hint":"Multiply length, width and height.","passage":""},{"id":"oh-y711-v1-9-volume-2","topic":"oh-y711-v1-9-volume","prompt":"A cuboid measures 4 cm by 3 cm by 4 cm. Find its volume in cm³.","choices":["49","48","47","51"],"correct":1,"explanation":"Volume = 4 × 3 × 4 = 48 cm³.","hint":"Multiply length, width and height.","passage":""},{"id":"oh-y711-v1-9-volume-3","topic":"oh-y711-v1-9-volume","prompt":"A cuboid measures 5 cm by 3 cm by 4 cm. Find its volume in cm³.","choices":["59","61","60","63"],"correct":2,"explanation":"Volume = 5 × 3 × 4 = 60 cm³.","hint":"Multiply length, width and height.","passage":""},{"id":"oh-y711-v1-9-volume-4","topic":"oh-y711-v1-9-volume","prompt":"A cuboid measures 6 cm by 3 cm by 4 cm. Find its volume in cm³.","choices":["75","73","71","72"],"correct":3,"explanation":"Volume = 6 × 3 × 4 = 72 cm³.","hint":"Multiply length, width and height.","passage":""},{"id":"oh-y711-v1-9-volume-5","topic":"oh-y711-v1-9-volume","prompt":"A cuboid measures 7 cm by 3 cm by 4 cm. Find its volume in cm³.","choices":["84","85","83","87"],"correct":0,"explanation":"Volume = 7 × 3 × 4 = 84 cm³.","hint":"Multiply length, width and height.","passage":""},{"id":"oh-y711-v1-9-volume-6","topic":"oh-y711-v1-9-volume","prompt":"A cuboid measures 8 cm by 3 cm by 4 cm. Find its volume in cm³.","choices":["97","96","95","99"],"correct":1,"explanation":"Volume = 8 × 3 × 4 = 96 cm³.","hint":"Multiply length, width and height.","passage":""},{"id":"oh-y711-v1-9-volume-7","topic":"oh-y711-v1-9-volume","prompt":"A cuboid measures 9 cm by 3 cm by 4 cm. Find its volume in cm³.","choices":["107","109","108","111"],"correct":2,"explanation":"Volume = 9 × 3 × 4 = 108 cm³.","hint":"Multiply length, width and height.","passage":""},{"id":"oh-y711-v1-9-volume-8","topic":"oh-y711-v1-9-volume","prompt":"A cuboid measures 10 cm by 3 cm by 4 cm. Find its volume in cm³.","choices":["123","121","119","120"],"correct":3,"explanation":"Volume = 10 × 3 × 4 = 120 cm³.","hint":"Multiply length, width and height.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-9-simultaneous','math','{"title":"Simultaneous equations","year":9,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-9-simultaneous-1","topic":"oh-y711-v1-9-simultaneous","prompt":"Solve x + y = 7 and x − y = 3. What is x?","choices":["5","6","4","8"],"correct":0,"explanation":"Add the equations: 2x = 10. Divide by 2: x = 5.","hint":"Adding the equations eliminates y.","passage":""},{"id":"oh-y711-v1-9-simultaneous-2","topic":"oh-y711-v1-9-simultaneous","prompt":"Solve x + y = 10 and x − y = 4. What is x?","choices":["8","7","6","10"],"correct":1,"explanation":"Add the equations: 2x = 14. Divide by 2: x = 7.","hint":"Adding the equations eliminates y.","passage":""},{"id":"oh-y711-v1-9-simultaneous-3","topic":"oh-y711-v1-9-simultaneous","prompt":"Solve x + y = 13 and x − y = 5. What is x?","choices":["8","10","9","12"],"correct":2,"explanation":"Add the equations: 2x = 18. Divide by 2: x = 9.","hint":"Adding the equations eliminates y.","passage":""},{"id":"oh-y711-v1-9-simultaneous-4","topic":"oh-y711-v1-9-simultaneous","prompt":"Solve x + y = 16 and x − y = 6. What is x?","choices":["14","12","10","11"],"correct":3,"explanation":"Add the equations: 2x = 22. Divide by 2: x = 11.","hint":"Adding the equations eliminates y.","passage":""},{"id":"oh-y711-v1-9-simultaneous-5","topic":"oh-y711-v1-9-simultaneous","prompt":"Solve x + y = 19 and x − y = 7. What is x?","choices":["13","14","12","16"],"correct":0,"explanation":"Add the equations: 2x = 26. Divide by 2: x = 13.","hint":"Adding the equations eliminates y.","passage":""},{"id":"oh-y711-v1-9-simultaneous-6","topic":"oh-y711-v1-9-simultaneous","prompt":"Solve x + y = 22 and x − y = 8. What is x?","choices":["16","15","14","18"],"correct":1,"explanation":"Add the equations: 2x = 30. Divide by 2: x = 15.","hint":"Adding the equations eliminates y.","passage":""},{"id":"oh-y711-v1-9-simultaneous-7","topic":"oh-y711-v1-9-simultaneous","prompt":"Solve x + y = 25 and x − y = 9. What is x?","choices":["16","18","17","20"],"correct":2,"explanation":"Add the equations: 2x = 34. Divide by 2: x = 17.","hint":"Adding the equations eliminates y.","passage":""},{"id":"oh-y711-v1-9-simultaneous-8","topic":"oh-y711-v1-9-simultaneous","prompt":"Solve x + y = 28 and x − y = 10. What is x?","choices":["22","20","18","19"],"correct":3,"explanation":"Add the equations: 2x = 38. Divide by 2: x = 19.","hint":"Adding the equations eliminates y.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-10-factorising','math','{"title":"Factorising quadratics","year":10,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-10-factorising-1","topic":"oh-y711-v1-10-factorising","prompt":"Factorise x² + 3x + 2.","choices":["(x + 1)(x + 2)","(x − 1)(x − 2)","(x + 1)(x − 2)","(x + 2)(x + 3)"],"correct":0,"explanation":"The numbers 1 and 2 add to 3 and multiply to 2.","hint":"Find two numbers with the required sum and product.","passage":""},{"id":"oh-y711-v1-10-factorising-2","topic":"oh-y711-v1-10-factorising","prompt":"Factorise x² + 5x + 6.","choices":["(x − 2)(x − 3)","(x + 2)(x + 3)","(x + 2)(x − 3)","(x + 3)(x + 4)"],"correct":1,"explanation":"The numbers 2 and 3 add to 5 and multiply to 6.","hint":"Find two numbers with the required sum and product.","passage":""},{"id":"oh-y711-v1-10-factorising-3","topic":"oh-y711-v1-10-factorising","prompt":"Factorise x² + 7x + 12.","choices":["(x + 3)(x − 4)","(x − 3)(x − 4)","(x + 3)(x + 4)","(x + 4)(x + 5)"],"correct":2,"explanation":"The numbers 3 and 4 add to 7 and multiply to 12.","hint":"Find two numbers with the required sum and product.","passage":""},{"id":"oh-y711-v1-10-factorising-4","topic":"oh-y711-v1-10-factorising","prompt":"Factorise x² + 9x + 20.","choices":["(x + 5)(x + 6)","(x − 4)(x − 5)","(x + 4)(x − 5)","(x + 4)(x + 5)"],"correct":3,"explanation":"The numbers 4 and 5 add to 9 and multiply to 20.","hint":"Find two numbers with the required sum and product.","passage":""},{"id":"oh-y711-v1-10-factorising-5","topic":"oh-y711-v1-10-factorising","prompt":"Factorise x² + 11x + 30.","choices":["(x + 5)(x + 6)","(x − 5)(x − 6)","(x + 5)(x − 6)","(x + 6)(x + 7)"],"correct":0,"explanation":"The numbers 5 and 6 add to 11 and multiply to 30.","hint":"Find two numbers with the required sum and product.","passage":""},{"id":"oh-y711-v1-10-factorising-6","topic":"oh-y711-v1-10-factorising","prompt":"Factorise x² + 13x + 42.","choices":["(x − 6)(x − 7)","(x + 6)(x + 7)","(x + 6)(x − 7)","(x + 7)(x + 8)"],"correct":1,"explanation":"The numbers 6 and 7 add to 13 and multiply to 42.","hint":"Find two numbers with the required sum and product.","passage":""},{"id":"oh-y711-v1-10-factorising-7","topic":"oh-y711-v1-10-factorising","prompt":"Factorise x² + 15x + 56.","choices":["(x + 7)(x − 8)","(x − 7)(x − 8)","(x + 7)(x + 8)","(x + 8)(x + 9)"],"correct":2,"explanation":"The numbers 7 and 8 add to 15 and multiply to 56.","hint":"Find two numbers with the required sum and product.","passage":""},{"id":"oh-y711-v1-10-factorising-8","topic":"oh-y711-v1-10-factorising","prompt":"Factorise x² + 17x + 72.","choices":["(x + 9)(x + 10)","(x − 8)(x − 9)","(x + 8)(x − 9)","(x + 8)(x + 9)"],"correct":3,"explanation":"The numbers 8 and 9 add to 17 and multiply to 72.","hint":"Find two numbers with the required sum and product.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-10-quadratics','math','{"title":"Solving factorised quadratics","year":10,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-10-quadratics-1","topic":"oh-y711-v1-10-quadratics","prompt":"Solve (x − 1)(x + 3) = 0.","choices":["x = 1 or x = −3","x = −1 or x = 3","x = 1 or x = 3","x = −1 or x = −3"],"correct":0,"explanation":"Set each factor to zero: x − 1 = 0 or x + 3 = 0.","hint":"At least one factor must equal zero.","passage":""},{"id":"oh-y711-v1-10-quadratics-2","topic":"oh-y711-v1-10-quadratics","prompt":"Solve (x − 2)(x + 4) = 0.","choices":["x = −2 or x = 4","x = 2 or x = −4","x = 2 or x = 4","x = −2 or x = −4"],"correct":1,"explanation":"Set each factor to zero: x − 2 = 0 or x + 4 = 0.","hint":"At least one factor must equal zero.","passage":""},{"id":"oh-y711-v1-10-quadratics-3","topic":"oh-y711-v1-10-quadratics","prompt":"Solve (x − 3)(x + 5) = 0.","choices":["x = 3 or x = 5","x = −3 or x = 5","x = 3 or x = −5","x = −3 or x = −5"],"correct":2,"explanation":"Set each factor to zero: x − 3 = 0 or x + 5 = 0.","hint":"At least one factor must equal zero.","passage":""},{"id":"oh-y711-v1-10-quadratics-4","topic":"oh-y711-v1-10-quadratics","prompt":"Solve (x − 4)(x + 6) = 0.","choices":["x = −4 or x = −6","x = −4 or x = 6","x = 4 or x = 6","x = 4 or x = −6"],"correct":3,"explanation":"Set each factor to zero: x − 4 = 0 or x + 6 = 0.","hint":"At least one factor must equal zero.","passage":""},{"id":"oh-y711-v1-10-quadratics-5","topic":"oh-y711-v1-10-quadratics","prompt":"Solve (x − 5)(x + 7) = 0.","choices":["x = 5 or x = −7","x = −5 or x = 7","x = 5 or x = 7","x = −5 or x = −7"],"correct":0,"explanation":"Set each factor to zero: x − 5 = 0 or x + 7 = 0.","hint":"At least one factor must equal zero.","passage":""},{"id":"oh-y711-v1-10-quadratics-6","topic":"oh-y711-v1-10-quadratics","prompt":"Solve (x − 6)(x + 8) = 0.","choices":["x = −6 or x = 8","x = 6 or x = −8","x = 6 or x = 8","x = −6 or x = −8"],"correct":1,"explanation":"Set each factor to zero: x − 6 = 0 or x + 8 = 0.","hint":"At least one factor must equal zero.","passage":""},{"id":"oh-y711-v1-10-quadratics-7","topic":"oh-y711-v1-10-quadratics","prompt":"Solve (x − 7)(x + 9) = 0.","choices":["x = 7 or x = 9","x = −7 or x = 9","x = 7 or x = −9","x = −7 or x = −9"],"correct":2,"explanation":"Set each factor to zero: x − 7 = 0 or x + 9 = 0.","hint":"At least one factor must equal zero.","passage":""},{"id":"oh-y711-v1-10-quadratics-8","topic":"oh-y711-v1-10-quadratics","prompt":"Solve (x − 8)(x + 10) = 0.","choices":["x = −8 or x = −10","x = −8 or x = 10","x = 8 or x = 10","x = 8 or x = −10"],"correct":3,"explanation":"Set each factor to zero: x − 8 = 0 or x + 10 = 0.","hint":"At least one factor must equal zero.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-10-trigonometry','math','{"title":"Right-angle trigonometry","year":10,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-10-trigonometry-1","topic":"oh-y711-v1-10-trigonometry","prompt":"A right-angled triangle has a 30° angle and hypotenuse 8 cm. Using sin 30° = 0.5, find the opposite side in cm.","choices":["4","5","3","7"],"correct":0,"explanation":"Opposite = 8 × 0.5 = 4 cm.","hint":"Sine = opposite ÷ hypotenuse.","passage":""},{"id":"oh-y711-v1-10-trigonometry-2","topic":"oh-y711-v1-10-trigonometry","prompt":"A right-angled triangle has a 30° angle and hypotenuse 10 cm. Using sin 30° = 0.5, find the opposite side in cm.","choices":["6","5","4","8"],"correct":1,"explanation":"Opposite = 10 × 0.5 = 5 cm.","hint":"Sine = opposite ÷ hypotenuse.","passage":""},{"id":"oh-y711-v1-10-trigonometry-3","topic":"oh-y711-v1-10-trigonometry","prompt":"A right-angled triangle has a 30° angle and hypotenuse 12 cm. Using sin 30° = 0.5, find the opposite side in cm.","choices":["5","7","6","9"],"correct":2,"explanation":"Opposite = 12 × 0.5 = 6 cm.","hint":"Sine = opposite ÷ hypotenuse.","passage":""},{"id":"oh-y711-v1-10-trigonometry-4","topic":"oh-y711-v1-10-trigonometry","prompt":"A right-angled triangle has a 30° angle and hypotenuse 14 cm. Using sin 30° = 0.5, find the opposite side in cm.","choices":["10","8","6","7"],"correct":3,"explanation":"Opposite = 14 × 0.5 = 7 cm.","hint":"Sine = opposite ÷ hypotenuse.","passage":""},{"id":"oh-y711-v1-10-trigonometry-5","topic":"oh-y711-v1-10-trigonometry","prompt":"A right-angled triangle has a 30° angle and hypotenuse 16 cm. Using sin 30° = 0.5, find the opposite side in cm.","choices":["8","9","7","11"],"correct":0,"explanation":"Opposite = 16 × 0.5 = 8 cm.","hint":"Sine = opposite ÷ hypotenuse.","passage":""},{"id":"oh-y711-v1-10-trigonometry-6","topic":"oh-y711-v1-10-trigonometry","prompt":"A right-angled triangle has a 30° angle and hypotenuse 18 cm. Using sin 30° = 0.5, find the opposite side in cm.","choices":["10","9","8","12"],"correct":1,"explanation":"Opposite = 18 × 0.5 = 9 cm.","hint":"Sine = opposite ÷ hypotenuse.","passage":""},{"id":"oh-y711-v1-10-trigonometry-7","topic":"oh-y711-v1-10-trigonometry","prompt":"A right-angled triangle has a 30° angle and hypotenuse 20 cm. Using sin 30° = 0.5, find the opposite side in cm.","choices":["9","11","10","13"],"correct":2,"explanation":"Opposite = 20 × 0.5 = 10 cm.","hint":"Sine = opposite ÷ hypotenuse.","passage":""},{"id":"oh-y711-v1-10-trigonometry-8","topic":"oh-y711-v1-10-trigonometry","prompt":"A right-angled triangle has a 30° angle and hypotenuse 22 cm. Using sin 30° = 0.5, find the opposite side in cm.","choices":["14","12","10","11"],"correct":3,"explanation":"Opposite = 22 × 0.5 = 11 cm.","hint":"Sine = opposite ÷ hypotenuse.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-10-compound','math','{"title":"Compound interest","year":10,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-10-compound-1","topic":"oh-y711-v1-10-compound","prompt":"£200 earns 10% compound interest each year for 2 years. What is the final balance?","choices":["£242.00","£240.00","£220.00","£204.00"],"correct":0,"explanation":"Use the multiplier twice: £200 × 1.1² = £242.00.","hint":"The second year’s interest is on the increased balance.","passage":""},{"id":"oh-y711-v1-10-compound-2","topic":"oh-y711-v1-10-compound","prompt":"£300 earns 10% compound interest each year for 2 years. What is the final balance?","choices":["£360.00","£363.00","£330.00","£306.00"],"correct":1,"explanation":"Use the multiplier twice: £300 × 1.1² = £363.00.","hint":"The second year’s interest is on the increased balance.","passage":""},{"id":"oh-y711-v1-10-compound-3","topic":"oh-y711-v1-10-compound","prompt":"£400 earns 10% compound interest each year for 2 years. What is the final balance?","choices":["£440.00","£480.00","£484.00","£408.00"],"correct":2,"explanation":"Use the multiplier twice: £400 × 1.1² = £484.00.","hint":"The second year’s interest is on the increased balance.","passage":""},{"id":"oh-y711-v1-10-compound-4","topic":"oh-y711-v1-10-compound","prompt":"£500 earns 10% compound interest each year for 2 years. What is the final balance?","choices":["£510.00","£600.00","£550.00","£605.00"],"correct":3,"explanation":"Use the multiplier twice: £500 × 1.1² = £605.00.","hint":"The second year’s interest is on the increased balance.","passage":""},{"id":"oh-y711-v1-10-compound-5","topic":"oh-y711-v1-10-compound","prompt":"£600 earns 10% compound interest each year for 2 years. What is the final balance?","choices":["£726.00","£720.00","£660.00","£612.00"],"correct":0,"explanation":"Use the multiplier twice: £600 × 1.1² = £726.00.","hint":"The second year’s interest is on the increased balance.","passage":""},{"id":"oh-y711-v1-10-compound-6","topic":"oh-y711-v1-10-compound","prompt":"£700 earns 10% compound interest each year for 2 years. What is the final balance?","choices":["£840.00","£847.00","£770.00","£714.00"],"correct":1,"explanation":"Use the multiplier twice: £700 × 1.1² = £847.00.","hint":"The second year’s interest is on the increased balance.","passage":""},{"id":"oh-y711-v1-10-compound-7","topic":"oh-y711-v1-10-compound","prompt":"£800 earns 10% compound interest each year for 2 years. What is the final balance?","choices":["£880.00","£960.00","£968.00","£816.00"],"correct":2,"explanation":"Use the multiplier twice: £800 × 1.1² = £968.00.","hint":"The second year’s interest is on the increased balance.","passage":""},{"id":"oh-y711-v1-10-compound-8","topic":"oh-y711-v1-10-compound","prompt":"£900 earns 10% compound interest each year for 2 years. What is the final balance?","choices":["£918.00","£1080.00","£990.00","£1089.00"],"correct":3,"explanation":"Use the multiplier twice: £900 × 1.1² = £1089.00.","hint":"The second year’s interest is on the increased balance.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-10-reverse','math','{"title":"Reverse percentages","year":10,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-10-reverse-1","topic":"oh-y711-v1-10-reverse","prompt":"After a 20% increase, a price is £60. What was the original price in pounds?","choices":["50","51","49","53"],"correct":0,"explanation":"Divide by 1.2: 60 ÷ 1.2 = 50.","hint":"The new price is 120% of the original.","passage":""},{"id":"oh-y711-v1-10-reverse-2","topic":"oh-y711-v1-10-reverse","prompt":"After a 20% increase, a price is £72. What was the original price in pounds?","choices":["61","60","59","63"],"correct":1,"explanation":"Divide by 1.2: 72 ÷ 1.2 = 60.","hint":"The new price is 120% of the original.","passage":""},{"id":"oh-y711-v1-10-reverse-3","topic":"oh-y711-v1-10-reverse","prompt":"After a 20% increase, a price is £84. What was the original price in pounds?","choices":["69","71","70","73"],"correct":2,"explanation":"Divide by 1.2: 84 ÷ 1.2 = 70.","hint":"The new price is 120% of the original.","passage":""},{"id":"oh-y711-v1-10-reverse-4","topic":"oh-y711-v1-10-reverse","prompt":"After a 20% increase, a price is £96. What was the original price in pounds?","choices":["83","81","79","80"],"correct":3,"explanation":"Divide by 1.2: 96 ÷ 1.2 = 80.","hint":"The new price is 120% of the original.","passage":""},{"id":"oh-y711-v1-10-reverse-5","topic":"oh-y711-v1-10-reverse","prompt":"After a 20% increase, a price is £108. What was the original price in pounds?","choices":["90","91","89","93"],"correct":0,"explanation":"Divide by 1.2: 108 ÷ 1.2 = 90.","hint":"The new price is 120% of the original.","passage":""},{"id":"oh-y711-v1-10-reverse-6","topic":"oh-y711-v1-10-reverse","prompt":"After a 20% increase, a price is £120. What was the original price in pounds?","choices":["101","100","99","103"],"correct":1,"explanation":"Divide by 1.2: 120 ÷ 1.2 = 100.","hint":"The new price is 120% of the original.","passage":""},{"id":"oh-y711-v1-10-reverse-7","topic":"oh-y711-v1-10-reverse","prompt":"After a 20% increase, a price is £132. What was the original price in pounds?","choices":["109","111","110","113"],"correct":2,"explanation":"Divide by 1.2: 132 ÷ 1.2 = 110.","hint":"The new price is 120% of the original.","passage":""},{"id":"oh-y711-v1-10-reverse-8","topic":"oh-y711-v1-10-reverse","prompt":"After a 20% increase, a price is £144. What was the original price in pounds?","choices":["123","121","119","120"],"correct":3,"explanation":"Divide by 1.2: 144 ÷ 1.2 = 120.","hint":"The new price is 120% of the original.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-10-similarity','math','{"title":"Similar shapes: area","year":10,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-10-similarity-1","topic":"oh-y711-v1-10-similarity","prompt":"Two similar shapes have length scale factor 2 from small to large. The smaller area is 3 cm². Find the larger area in cm².","choices":["12","13","11","15"],"correct":0,"explanation":"Area scale factor = 2² = 4. Multiply 3 by this to get 12 cm².","hint":"Square the length scale factor for area.","passage":""},{"id":"oh-y711-v1-10-similarity-2","topic":"oh-y711-v1-10-similarity","prompt":"Two similar shapes have length scale factor 3 from small to large. The smaller area is 3 cm². Find the larger area in cm².","choices":["28","27","26","30"],"correct":1,"explanation":"Area scale factor = 3² = 9. Multiply 3 by this to get 27 cm².","hint":"Square the length scale factor for area.","passage":""},{"id":"oh-y711-v1-10-similarity-3","topic":"oh-y711-v1-10-similarity","prompt":"Two similar shapes have length scale factor 4 from small to large. The smaller area is 3 cm². Find the larger area in cm².","choices":["47","49","48","51"],"correct":2,"explanation":"Area scale factor = 4² = 16. Multiply 3 by this to get 48 cm².","hint":"Square the length scale factor for area.","passage":""},{"id":"oh-y711-v1-10-similarity-4","topic":"oh-y711-v1-10-similarity","prompt":"Two similar shapes have length scale factor 5 from small to large. The smaller area is 3 cm². Find the larger area in cm².","choices":["78","76","74","75"],"correct":3,"explanation":"Area scale factor = 5² = 25. Multiply 3 by this to get 75 cm².","hint":"Square the length scale factor for area.","passage":""},{"id":"oh-y711-v1-10-similarity-5","topic":"oh-y711-v1-10-similarity","prompt":"Two similar shapes have length scale factor 6 from small to large. The smaller area is 3 cm². Find the larger area in cm².","choices":["108","109","107","111"],"correct":0,"explanation":"Area scale factor = 6² = 36. Multiply 3 by this to get 108 cm².","hint":"Square the length scale factor for area.","passage":""},{"id":"oh-y711-v1-10-similarity-6","topic":"oh-y711-v1-10-similarity","prompt":"Two similar shapes have length scale factor 7 from small to large. The smaller area is 3 cm². Find the larger area in cm².","choices":["148","147","146","150"],"correct":1,"explanation":"Area scale factor = 7² = 49. Multiply 3 by this to get 147 cm².","hint":"Square the length scale factor for area.","passage":""},{"id":"oh-y711-v1-10-similarity-7","topic":"oh-y711-v1-10-similarity","prompt":"Two similar shapes have length scale factor 8 from small to large. The smaller area is 3 cm². Find the larger area in cm².","choices":["191","193","192","195"],"correct":2,"explanation":"Area scale factor = 8² = 64. Multiply 3 by this to get 192 cm².","hint":"Square the length scale factor for area.","passage":""},{"id":"oh-y711-v1-10-similarity-8","topic":"oh-y711-v1-10-similarity","prompt":"Two similar shapes have length scale factor 9 from small to large. The smaller area is 3 cm². Find the larger area in cm².","choices":["246","244","242","243"],"correct":3,"explanation":"Area scale factor = 9² = 81. Multiply 3 by this to get 243 cm².","hint":"Square the length scale factor for area.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-10-density','math','{"title":"Density, mass and volume","year":10,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-10-density-1","topic":"oh-y711-v1-10-density","prompt":"An object has mass 18 g and volume 6 cm³. Find its density in g/cm³.","choices":["3","4","2","6"],"correct":0,"explanation":"Density = mass ÷ volume = 18 ÷ 6 = 3 g/cm³.","hint":"Density measures mass per unit volume.","passage":""},{"id":"oh-y711-v1-10-density-2","topic":"oh-y711-v1-10-density","prompt":"An object has mass 28 g and volume 7 cm³. Find its density in g/cm³.","choices":["5","4","3","7"],"correct":1,"explanation":"Density = mass ÷ volume = 28 ÷ 7 = 4 g/cm³.","hint":"Density measures mass per unit volume.","passage":""},{"id":"oh-y711-v1-10-density-3","topic":"oh-y711-v1-10-density","prompt":"An object has mass 40 g and volume 8 cm³. Find its density in g/cm³.","choices":["4","6","5","8"],"correct":2,"explanation":"Density = mass ÷ volume = 40 ÷ 8 = 5 g/cm³.","hint":"Density measures mass per unit volume.","passage":""},{"id":"oh-y711-v1-10-density-4","topic":"oh-y711-v1-10-density","prompt":"An object has mass 54 g and volume 9 cm³. Find its density in g/cm³.","choices":["9","7","5","6"],"correct":3,"explanation":"Density = mass ÷ volume = 54 ÷ 9 = 6 g/cm³.","hint":"Density measures mass per unit volume.","passage":""},{"id":"oh-y711-v1-10-density-5","topic":"oh-y711-v1-10-density","prompt":"An object has mass 70 g and volume 10 cm³. Find its density in g/cm³.","choices":["7","8","6","10"],"correct":0,"explanation":"Density = mass ÷ volume = 70 ÷ 10 = 7 g/cm³.","hint":"Density measures mass per unit volume.","passage":""},{"id":"oh-y711-v1-10-density-6","topic":"oh-y711-v1-10-density","prompt":"An object has mass 88 g and volume 11 cm³. Find its density in g/cm³.","choices":["9","8","7","11"],"correct":1,"explanation":"Density = mass ÷ volume = 88 ÷ 11 = 8 g/cm³.","hint":"Density measures mass per unit volume.","passage":""},{"id":"oh-y711-v1-10-density-7","topic":"oh-y711-v1-10-density","prompt":"An object has mass 108 g and volume 12 cm³. Find its density in g/cm³.","choices":["8","10","9","12"],"correct":2,"explanation":"Density = mass ÷ volume = 108 ÷ 12 = 9 g/cm³.","hint":"Density measures mass per unit volume.","passage":""},{"id":"oh-y711-v1-10-density-8","topic":"oh-y711-v1-10-density","prompt":"An object has mass 130 g and volume 13 cm³. Find its density in g/cm³.","choices":["13","11","9","10"],"correct":3,"explanation":"Density = mass ÷ volume = 130 ÷ 13 = 10 g/cm³.","hint":"Density measures mass per unit volume.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-11-functions','math','{"title":"Composite functions","year":11,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-11-functions-1","topic":"oh-y711-v1-11-functions","prompt":"f(x) = 2x + 1 and g(x) = x + 1. Find f(g(3)).","choices":["9","10","8","12"],"correct":0,"explanation":"First g(3) = 4. Then f(4) = 9.","hint":"Apply the inner function g first.","passage":""},{"id":"oh-y711-v1-11-functions-2","topic":"oh-y711-v1-11-functions","prompt":"f(x) = 2x + 1 and g(x) = x + 2. Find f(g(4)).","choices":["14","13","12","16"],"correct":1,"explanation":"First g(4) = 6. Then f(6) = 13.","hint":"Apply the inner function g first.","passage":""},{"id":"oh-y711-v1-11-functions-3","topic":"oh-y711-v1-11-functions","prompt":"f(x) = 2x + 1 and g(x) = x + 3. Find f(g(5)).","choices":["16","18","17","20"],"correct":2,"explanation":"First g(5) = 8. Then f(8) = 17.","hint":"Apply the inner function g first.","passage":""},{"id":"oh-y711-v1-11-functions-4","topic":"oh-y711-v1-11-functions","prompt":"f(x) = 2x + 1 and g(x) = x + 4. Find f(g(6)).","choices":["24","22","20","21"],"correct":3,"explanation":"First g(6) = 10. Then f(10) = 21.","hint":"Apply the inner function g first.","passage":""},{"id":"oh-y711-v1-11-functions-5","topic":"oh-y711-v1-11-functions","prompt":"f(x) = 2x + 1 and g(x) = x + 5. Find f(g(7)).","choices":["25","26","24","28"],"correct":0,"explanation":"First g(7) = 12. Then f(12) = 25.","hint":"Apply the inner function g first.","passage":""},{"id":"oh-y711-v1-11-functions-6","topic":"oh-y711-v1-11-functions","prompt":"f(x) = 2x + 1 and g(x) = x + 6. Find f(g(8)).","choices":["30","29","28","32"],"correct":1,"explanation":"First g(8) = 14. Then f(14) = 29.","hint":"Apply the inner function g first.","passage":""},{"id":"oh-y711-v1-11-functions-7","topic":"oh-y711-v1-11-functions","prompt":"f(x) = 2x + 1 and g(x) = x + 7. Find f(g(9)).","choices":["32","34","33","36"],"correct":2,"explanation":"First g(9) = 16. Then f(16) = 33.","hint":"Apply the inner function g first.","passage":""},{"id":"oh-y711-v1-11-functions-8","topic":"oh-y711-v1-11-functions","prompt":"f(x) = 2x + 1 and g(x) = x + 8. Find f(g(10)).","choices":["40","38","36","37"],"correct":3,"explanation":"First g(10) = 18. Then f(18) = 37.","hint":"Apply the inner function g first.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-11-proportion','math','{"title":"Inverse proportion","year":11,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-11-proportion-1","topic":"oh-y711-v1-11-proportion","prompt":"y is inversely proportional to x. When x = 2, y = 12. Find y when x = 6.","choices":["4","5","3","7"],"correct":0,"explanation":"xy is constant at 24. Therefore y = 24 ÷ 6 = 4.","hint":"For inverse proportion, the product xy stays constant.","passage":""},{"id":"oh-y711-v1-11-proportion-2","topic":"oh-y711-v1-11-proportion","prompt":"y is inversely proportional to x. When x = 2, y = 18. Find y when x = 6.","choices":["7","6","5","9"],"correct":1,"explanation":"xy is constant at 36. Therefore y = 36 ÷ 6 = 6.","hint":"For inverse proportion, the product xy stays constant.","passage":""},{"id":"oh-y711-v1-11-proportion-3","topic":"oh-y711-v1-11-proportion","prompt":"y is inversely proportional to x. When x = 2, y = 24. Find y when x = 6.","choices":["7","9","8","11"],"correct":2,"explanation":"xy is constant at 48. Therefore y = 48 ÷ 6 = 8.","hint":"For inverse proportion, the product xy stays constant.","passage":""},{"id":"oh-y711-v1-11-proportion-4","topic":"oh-y711-v1-11-proportion","prompt":"y is inversely proportional to x. When x = 2, y = 30. Find y when x = 6.","choices":["13","11","9","10"],"correct":3,"explanation":"xy is constant at 60. Therefore y = 60 ÷ 6 = 10.","hint":"For inverse proportion, the product xy stays constant.","passage":""},{"id":"oh-y711-v1-11-proportion-5","topic":"oh-y711-v1-11-proportion","prompt":"y is inversely proportional to x. When x = 2, y = 36. Find y when x = 6.","choices":["12","13","11","15"],"correct":0,"explanation":"xy is constant at 72. Therefore y = 72 ÷ 6 = 12.","hint":"For inverse proportion, the product xy stays constant.","passage":""},{"id":"oh-y711-v1-11-proportion-6","topic":"oh-y711-v1-11-proportion","prompt":"y is inversely proportional to x. When x = 2, y = 42. Find y when x = 6.","choices":["15","14","13","17"],"correct":1,"explanation":"xy is constant at 84. Therefore y = 84 ÷ 6 = 14.","hint":"For inverse proportion, the product xy stays constant.","passage":""},{"id":"oh-y711-v1-11-proportion-7","topic":"oh-y711-v1-11-proportion","prompt":"y is inversely proportional to x. When x = 2, y = 48. Find y when x = 6.","choices":["15","17","16","19"],"correct":2,"explanation":"xy is constant at 96. Therefore y = 96 ÷ 6 = 16.","hint":"For inverse proportion, the product xy stays constant.","passage":""},{"id":"oh-y711-v1-11-proportion-8","topic":"oh-y711-v1-11-proportion","prompt":"y is inversely proportional to x. When x = 2, y = 54. Find y when x = 6.","choices":["21","19","17","18"],"correct":3,"explanation":"xy is constant at 108. Therefore y = 108 ÷ 6 = 18.","hint":"For inverse proportion, the product xy stays constant.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-11-surds','math','{"title":"Simplifying surds","year":11,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-11-surds-1","topic":"oh-y711-v1-11-surds","prompt":"Simplify √18.","choices":["3√2","2√2","4√2","3√3"],"correct":0,"explanation":"18 = 9 × 2, so the answer is 3√2.","hint":"Factor out the largest square number.","passage":""},{"id":"oh-y711-v1-11-surds-2","topic":"oh-y711-v1-11-surds","prompt":"Simplify √32.","choices":["3√2","4√2","5√2","4√3"],"correct":1,"explanation":"32 = 16 × 2, so the answer is 4√2.","hint":"Factor out the largest square number.","passage":""},{"id":"oh-y711-v1-11-surds-3","topic":"oh-y711-v1-11-surds","prompt":"Simplify √50.","choices":["6√2","4√2","5√2","5√3"],"correct":2,"explanation":"50 = 25 × 2, so the answer is 5√2.","hint":"Factor out the largest square number.","passage":""},{"id":"oh-y711-v1-11-surds-4","topic":"oh-y711-v1-11-surds","prompt":"Simplify √72.","choices":["6√3","5√2","7√2","6√2"],"correct":3,"explanation":"72 = 36 × 2, so the answer is 6√2.","hint":"Factor out the largest square number.","passage":""},{"id":"oh-y711-v1-11-surds-5","topic":"oh-y711-v1-11-surds","prompt":"Simplify √98.","choices":["7√2","6√2","8√2","7√3"],"correct":0,"explanation":"98 = 49 × 2, so the answer is 7√2.","hint":"Factor out the largest square number.","passage":""},{"id":"oh-y711-v1-11-surds-6","topic":"oh-y711-v1-11-surds","prompt":"Simplify √128.","choices":["7√2","8√2","9√2","8√3"],"correct":1,"explanation":"128 = 64 × 2, so the answer is 8√2.","hint":"Factor out the largest square number.","passage":""},{"id":"oh-y711-v1-11-surds-7","topic":"oh-y711-v1-11-surds","prompt":"Simplify √162.","choices":["10√2","8√2","9√2","9√3"],"correct":2,"explanation":"162 = 81 × 2, so the answer is 9√2.","hint":"Factor out the largest square number.","passage":""},{"id":"oh-y711-v1-11-surds-8","topic":"oh-y711-v1-11-surds","prompt":"Simplify √200.","choices":["10√3","9√2","11√2","10√2"],"correct":3,"explanation":"200 = 100 × 2, so the answer is 10√2.","hint":"Factor out the largest square number.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-11-bounds','math','{"title":"Upper bounds","year":11,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-11-bounds-1","topic":"oh-y711-v1-11-bounds","prompt":"A length is 11 cm to the nearest centimetre. What is its upper bound?","choices":["11.5 cm","10.5 cm","12 cm","11.05 cm"],"correct":0,"explanation":"The length is at least 10.5 cm and less than 11.5 cm. The upper bound is 11.5 cm.","hint":"Add half the rounding unit to find the upper bound.","passage":""},{"id":"oh-y711-v1-11-bounds-2","topic":"oh-y711-v1-11-bounds","prompt":"A length is 12 cm to the nearest centimetre. What is its upper bound?","choices":["11.5 cm","12.5 cm","13 cm","12.05 cm"],"correct":1,"explanation":"The length is at least 11.5 cm and less than 12.5 cm. The upper bound is 12.5 cm.","hint":"Add half the rounding unit to find the upper bound.","passage":""},{"id":"oh-y711-v1-11-bounds-3","topic":"oh-y711-v1-11-bounds","prompt":"A length is 13 cm to the nearest centimetre. What is its upper bound?","choices":["14 cm","12.5 cm","13.5 cm","13.05 cm"],"correct":2,"explanation":"The length is at least 12.5 cm and less than 13.5 cm. The upper bound is 13.5 cm.","hint":"Add half the rounding unit to find the upper bound.","passage":""},{"id":"oh-y711-v1-11-bounds-4","topic":"oh-y711-v1-11-bounds","prompt":"A length is 14 cm to the nearest centimetre. What is its upper bound?","choices":["14.05 cm","13.5 cm","15 cm","14.5 cm"],"correct":3,"explanation":"The length is at least 13.5 cm and less than 14.5 cm. The upper bound is 14.5 cm.","hint":"Add half the rounding unit to find the upper bound.","passage":""},{"id":"oh-y711-v1-11-bounds-5","topic":"oh-y711-v1-11-bounds","prompt":"A length is 15 cm to the nearest centimetre. What is its upper bound?","choices":["15.5 cm","14.5 cm","16 cm","15.05 cm"],"correct":0,"explanation":"The length is at least 14.5 cm and less than 15.5 cm. The upper bound is 15.5 cm.","hint":"Add half the rounding unit to find the upper bound.","passage":""},{"id":"oh-y711-v1-11-bounds-6","topic":"oh-y711-v1-11-bounds","prompt":"A length is 16 cm to the nearest centimetre. What is its upper bound?","choices":["15.5 cm","16.5 cm","17 cm","16.05 cm"],"correct":1,"explanation":"The length is at least 15.5 cm and less than 16.5 cm. The upper bound is 16.5 cm.","hint":"Add half the rounding unit to find the upper bound.","passage":""},{"id":"oh-y711-v1-11-bounds-7","topic":"oh-y711-v1-11-bounds","prompt":"A length is 17 cm to the nearest centimetre. What is its upper bound?","choices":["18 cm","16.5 cm","17.5 cm","17.05 cm"],"correct":2,"explanation":"The length is at least 16.5 cm and less than 17.5 cm. The upper bound is 17.5 cm.","hint":"Add half the rounding unit to find the upper bound.","passage":""},{"id":"oh-y711-v1-11-bounds-8","topic":"oh-y711-v1-11-bounds","prompt":"A length is 18 cm to the nearest centimetre. What is its upper bound?","choices":["18.05 cm","17.5 cm","19 cm","18.5 cm"],"correct":3,"explanation":"The length is at least 17.5 cm and less than 18.5 cm. The upper bound is 18.5 cm.","hint":"Add half the rounding unit to find the upper bound.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-11-conditional','math','{"title":"Probability without replacement","year":11,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-11-conditional-1","topic":"oh-y711-v1-11-conditional","prompt":"A bag has 3 red and 3 blue counters. One red is taken and not replaced. What is the probability the next counter is red?","choices":["2/5","1/2","1/3","1"],"correct":0,"explanation":"There are now 2 red counters out of 5, giving 2/5.","hint":"Reduce both the red count and the total by one.","passage":""},{"id":"oh-y711-v1-11-conditional-2","topic":"oh-y711-v1-11-conditional","prompt":"A bag has 4 red and 3 blue counters. One red is taken and not replaced. What is the probability the next counter is red?","choices":["4/7","1/2","3/7","1"],"correct":1,"explanation":"There are now 3 red counters out of 6, giving 1/2.","hint":"Reduce both the red count and the total by one.","passage":""},{"id":"oh-y711-v1-11-conditional-3","topic":"oh-y711-v1-11-conditional","prompt":"A bag has 5 red and 3 blue counters. One red is taken and not replaced. What is the probability the next counter is red?","choices":["1/2","5/8","4/7","1"],"correct":2,"explanation":"There are now 4 red counters out of 7, giving 4/7.","hint":"Reduce both the red count and the total by one.","passage":""},{"id":"oh-y711-v1-11-conditional-4","topic":"oh-y711-v1-11-conditional","prompt":"A bag has 6 red and 3 blue counters. One red is taken and not replaced. What is the probability the next counter is red?","choices":["1","2/3","5/9","5/8"],"correct":3,"explanation":"There are now 5 red counters out of 8, giving 5/8.","hint":"Reduce both the red count and the total by one.","passage":""},{"id":"oh-y711-v1-11-conditional-5","topic":"oh-y711-v1-11-conditional","prompt":"A bag has 7 red and 3 blue counters. One red is taken and not replaced. What is the probability the next counter is red?","choices":["2/3","7/10","3/5","1"],"correct":0,"explanation":"There are now 6 red counters out of 9, giving 2/3.","hint":"Reduce both the red count and the total by one.","passage":""},{"id":"oh-y711-v1-11-conditional-6","topic":"oh-y711-v1-11-conditional","prompt":"A bag has 8 red and 3 blue counters. One red is taken and not replaced. What is the probability the next counter is red?","choices":["8/11","7/10","7/11","1"],"correct":1,"explanation":"There are now 7 red counters out of 10, giving 7/10.","hint":"Reduce both the red count and the total by one.","passage":""},{"id":"oh-y711-v1-11-conditional-7","topic":"oh-y711-v1-11-conditional","prompt":"A bag has 9 red and 3 blue counters. One red is taken and not replaced. What is the probability the next counter is red?","choices":["2/3","3/4","8/11","1"],"correct":2,"explanation":"There are now 8 red counters out of 11, giving 8/11.","hint":"Reduce both the red count and the total by one.","passage":""},{"id":"oh-y711-v1-11-conditional-8","topic":"oh-y711-v1-11-conditional","prompt":"A bag has 10 red and 3 blue counters. One red is taken and not replaced. What is the probability the next counter is red?","choices":["1","10/13","9/13","3/4"],"correct":3,"explanation":"There are now 9 red counters out of 12, giving 3/4.","hint":"Reduce both the red count and the total by one.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-11-vectors','math','{"title":"Adding vectors","year":11,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-11-vectors-1","topic":"oh-y711-v1-11-vectors","prompt":"Vector a = (1, 2) and b = (2, −3). Write a + b as (horizontal, vertical).","choices":["(3, -1)","(3, 5)","(-1, -1)","(2, -1)"],"correct":0,"explanation":"Add horizontal components and vertical components separately: (3, -1).","hint":"Add matching components.","passage":""},{"id":"oh-y711-v1-11-vectors-2","topic":"oh-y711-v1-11-vectors","prompt":"Vector a = (2, 3) and b = (2, −3). Write a + b as (horizontal, vertical).","choices":["(4, 6)","(4, 0)","(0, 0)","(3, 0)"],"correct":1,"explanation":"Add horizontal components and vertical components separately: (4, 0).","hint":"Add matching components.","passage":""},{"id":"oh-y711-v1-11-vectors-3","topic":"oh-y711-v1-11-vectors","prompt":"Vector a = (3, 4) and b = (2, −3). Write a + b as (horizontal, vertical).","choices":["(1, 1)","(5, 7)","(5, 1)","(4, 1)"],"correct":2,"explanation":"Add horizontal components and vertical components separately: (5, 1).","hint":"Add matching components.","passage":""},{"id":"oh-y711-v1-11-vectors-4","topic":"oh-y711-v1-11-vectors","prompt":"Vector a = (4, 5) and b = (2, −3). Write a + b as (horizontal, vertical).","choices":["(5, 2)","(6, 8)","(2, 2)","(6, 2)"],"correct":3,"explanation":"Add horizontal components and vertical components separately: (6, 2).","hint":"Add matching components.","passage":""},{"id":"oh-y711-v1-11-vectors-5","topic":"oh-y711-v1-11-vectors","prompt":"Vector a = (5, 6) and b = (2, −3). Write a + b as (horizontal, vertical).","choices":["(7, 3)","(7, 9)","(3, 3)","(6, 3)"],"correct":0,"explanation":"Add horizontal components and vertical components separately: (7, 3).","hint":"Add matching components.","passage":""},{"id":"oh-y711-v1-11-vectors-6","topic":"oh-y711-v1-11-vectors","prompt":"Vector a = (6, 7) and b = (2, −3). Write a + b as (horizontal, vertical).","choices":["(8, 10)","(8, 4)","(4, 4)","(7, 4)"],"correct":1,"explanation":"Add horizontal components and vertical components separately: (8, 4).","hint":"Add matching components.","passage":""},{"id":"oh-y711-v1-11-vectors-7","topic":"oh-y711-v1-11-vectors","prompt":"Vector a = (7, 8) and b = (2, −3). Write a + b as (horizontal, vertical).","choices":["(5, 5)","(9, 11)","(9, 5)","(8, 5)"],"correct":2,"explanation":"Add horizontal components and vertical components separately: (9, 5).","hint":"Add matching components.","passage":""},{"id":"oh-y711-v1-11-vectors-8","topic":"oh-y711-v1-11-vectors","prompt":"Vector a = (8, 9) and b = (2, −3). Write a + b as (horizontal, vertical).","choices":["(9, 6)","(10, 12)","(6, 6)","(10, 6)"],"correct":3,"explanation":"Add horizontal components and vertical components separately: (10, 6).","hint":"Add matching components.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('oh-y711-v1-11-gradient','math','{"title":"Gradient between two points","year":11,"boards":["AQA","Edexcel"],"questions":[{"id":"oh-y711-v1-11-gradient-1","topic":"oh-y711-v1-11-gradient","prompt":"Find the gradient of the line through (1, 2) and (3, 6).","choices":["2","3","1","5"],"correct":0,"explanation":"Gradient = (6 − 2) ÷ (3 − 1) = 2.","hint":"Use change in y divided by change in x.","passage":""},{"id":"oh-y711-v1-11-gradient-2","topic":"oh-y711-v1-11-gradient","prompt":"Find the gradient of the line through (1, 3) and (3, 9).","choices":["4","3","2","6"],"correct":1,"explanation":"Gradient = (9 − 3) ÷ (3 − 1) = 3.","hint":"Use change in y divided by change in x.","passage":""},{"id":"oh-y711-v1-11-gradient-3","topic":"oh-y711-v1-11-gradient","prompt":"Find the gradient of the line through (1, 4) and (3, 12).","choices":["3","5","4","7"],"correct":2,"explanation":"Gradient = (12 − 4) ÷ (3 − 1) = 4.","hint":"Use change in y divided by change in x.","passage":""},{"id":"oh-y711-v1-11-gradient-4","topic":"oh-y711-v1-11-gradient","prompt":"Find the gradient of the line through (1, 5) and (3, 15).","choices":["8","6","4","5"],"correct":3,"explanation":"Gradient = (15 − 5) ÷ (3 − 1) = 5.","hint":"Use change in y divided by change in x.","passage":""},{"id":"oh-y711-v1-11-gradient-5","topic":"oh-y711-v1-11-gradient","prompt":"Find the gradient of the line through (1, 6) and (3, 18).","choices":["6","7","5","9"],"correct":0,"explanation":"Gradient = (18 − 6) ÷ (3 − 1) = 6.","hint":"Use change in y divided by change in x.","passage":""},{"id":"oh-y711-v1-11-gradient-6","topic":"oh-y711-v1-11-gradient","prompt":"Find the gradient of the line through (1, 7) and (3, 21).","choices":["8","7","6","10"],"correct":1,"explanation":"Gradient = (21 − 7) ÷ (3 − 1) = 7.","hint":"Use change in y divided by change in x.","passage":""},{"id":"oh-y711-v1-11-gradient-7","topic":"oh-y711-v1-11-gradient","prompt":"Find the gradient of the line through (1, 8) and (3, 24).","choices":["7","9","8","11"],"correct":2,"explanation":"Gradient = (24 − 8) ÷ (3 − 1) = 8.","hint":"Use change in y divided by change in x.","passage":""},{"id":"oh-y711-v1-11-gradient-8","topic":"oh-y711-v1-11-gradient","prompt":"Find the gradient of the line through (1, 9) and (3, 27).","choices":["12","10","8","9"],"correct":3,"explanation":"Gradient = (27 − 9) ÷ (3 − 1) = 9.","hint":"Use change in y divided by change in x.","passage":""}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
