INSERT INTO public.oh2_content(id,kind,data) VALUES('math-7-division','math','{"title":"Division","year":7,"boards":["AQA","Edexcel"],"questions":[{"prompt":"35 ÷ 7","choices":["5","6","7","8"],"correct":0,"explanation":"Find how many groups of seven fit.","hint":"Find how many groups of seven fit."},{"prompt":"42 ÷ 7","choices":["7","6","8","9"],"correct":1,"explanation":"Find how many groups of seven fit.","hint":"Find how many groups of seven fit."},{"prompt":"49 ÷ 7","choices":["9","8","7","10"],"correct":2,"explanation":"Find how many groups of seven fit.","hint":"Find how many groups of seven fit."},{"prompt":"56 ÷ 7","choices":["11","9","10","8"],"correct":3,"explanation":"Find how many groups of seven fit.","hint":"Find how many groups of seven fit."},{"prompt":"63 ÷ 7","choices":["9","10","11","12"],"correct":0,"explanation":"Find how many groups of seven fit.","hint":"Find how many groups of seven fit."},{"prompt":"70 ÷ 7","choices":["11","10","12","13"],"correct":1,"explanation":"Find how many groups of seven fit.","hint":"Find how many groups of seven fit."},{"prompt":"77 ÷ 7","choices":["13","12","11","14"],"correct":2,"explanation":"Find how many groups of seven fit.","hint":"Find how many groups of seven fit."},{"prompt":"84 ÷ 7","choices":["15","13","14","12"],"correct":3,"explanation":"Find how many groups of seven fit.","hint":"Find how many groups of seven fit."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-7-squares','math','{"title":"Squares","year":7,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Find 3².","choices":["9","10","11","12"],"correct":0,"explanation":"Multiply the number by itself.","hint":"Multiply the number by itself."},{"prompt":"Find 4².","choices":["17","16","18","19"],"correct":1,"explanation":"Multiply the number by itself.","hint":"Multiply the number by itself."},{"prompt":"Find 5².","choices":["27","26","25","28"],"correct":2,"explanation":"Multiply the number by itself.","hint":"Multiply the number by itself."},{"prompt":"Find 6².","choices":["39","37","38","36"],"correct":3,"explanation":"Multiply the number by itself.","hint":"Multiply the number by itself."},{"prompt":"Find 7².","choices":["49","50","51","52"],"correct":0,"explanation":"Multiply the number by itself.","hint":"Multiply the number by itself."},{"prompt":"Find 8².","choices":["65","64","66","67"],"correct":1,"explanation":"Multiply the number by itself.","hint":"Multiply the number by itself."},{"prompt":"Find 9².","choices":["83","82","81","84"],"correct":2,"explanation":"Multiply the number by itself.","hint":"Multiply the number by itself."},{"prompt":"Find 10².","choices":["103","101","102","100"],"correct":3,"explanation":"Multiply the number by itself.","hint":"Multiply the number by itself."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-7-cubes','math','{"title":"Cubes","year":7,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Find 2³.","choices":["8","9","10","11"],"correct":0,"explanation":"Multiply three copies of the number.","hint":"Multiply three copies of the number."},{"prompt":"Find 3³.","choices":["28","27","29","30"],"correct":1,"explanation":"Multiply three copies of the number.","hint":"Multiply three copies of the number."},{"prompt":"Find 4³.","choices":["66","65","64","67"],"correct":2,"explanation":"Multiply three copies of the number.","hint":"Multiply three copies of the number."},{"prompt":"Find 5³.","choices":["128","126","127","125"],"correct":3,"explanation":"Multiply three copies of the number.","hint":"Multiply three copies of the number."},{"prompt":"Find 6³.","choices":["216","217","218","219"],"correct":0,"explanation":"Multiply three copies of the number.","hint":"Multiply three copies of the number."},{"prompt":"Find 7³.","choices":["344","343","345","346"],"correct":1,"explanation":"Multiply three copies of the number.","hint":"Multiply three copies of the number."},{"prompt":"Find 8³.","choices":["514","513","512","515"],"correct":2,"explanation":"Multiply three copies of the number.","hint":"Multiply three copies of the number."},{"prompt":"Find 9³.","choices":["732","730","731","729"],"correct":3,"explanation":"Multiply three copies of the number.","hint":"Multiply three copies of the number."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
