INSERT INTO public.oh2_content(id,kind,data) VALUES('math-8-speed','math','{"title":"Speed","year":8,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A cyclist travels 12 km in 3 hours. Find the average speed in km/h.","choices":["4","5","6","7"],"correct":0,"explanation":"Average speed is distance divided by time.","hint":"Average speed is distance divided by time."},{"prompt":"A cyclist travels 24 km in 3 hours. Find the average speed in km/h.","choices":["9","8","10","11"],"correct":1,"explanation":"Average speed is distance divided by time.","hint":"Average speed is distance divided by time."},{"prompt":"A cyclist travels 36 km in 3 hours. Find the average speed in km/h.","choices":["14","13","12","15"],"correct":2,"explanation":"Average speed is distance divided by time.","hint":"Average speed is distance divided by time."},{"prompt":"A cyclist travels 48 km in 3 hours. Find the average speed in km/h.","choices":["19","17","18","16"],"correct":3,"explanation":"Average speed is distance divided by time.","hint":"Average speed is distance divided by time."},{"prompt":"A cyclist travels 60 km in 3 hours. Find the average speed in km/h.","choices":["20","21","22","23"],"correct":0,"explanation":"Average speed is distance divided by time.","hint":"Average speed is distance divided by time."},{"prompt":"A cyclist travels 72 km in 3 hours. Find the average speed in km/h.","choices":["25","24","26","27"],"correct":1,"explanation":"Average speed is distance divided by time.","hint":"Average speed is distance divided by time."},{"prompt":"A cyclist travels 84 km in 3 hours. Find the average speed in km/h.","choices":["30","29","28","31"],"correct":2,"explanation":"Average speed is distance divided by time.","hint":"Average speed is distance divided by time."},{"prompt":"A cyclist travels 96 km in 3 hours. Find the average speed in km/h.","choices":["35","33","34","32"],"correct":3,"explanation":"Average speed is distance divided by time.","hint":"Average speed is dista