INSERT INTO public.oh2_content(id,kind,data) VALUES('math-8-trapezium-area','math','{"title":"Trapezium area","year":8,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Parallel sides are 3 cm and 7 cm, height 4 cm. Find the trapezium area in cm².","choices":["20","21","22","23"],"correct":0,"explanation":"Add the parallel sides, multiply by height and divide by 2.","hint":"Add the parallel sides, multiply by height and divide by 2."},{"prompt":"Parallel sides are 4 cm and 8 cm, height 4 cm. Find the trapezium area in cm².","choices":["25","24","26","27"],"correct":1,"explanation":"Add the parallel sides, multiply by height and divide by 2.","hint":"Add the parallel sides, multiply by height and divide by 2."},{"prompt":"Parallel sides are 5 cm and 9 cm, height 4 cm. Find the trapezium area in cm².","choices":["30","29","28","31"],"correct":2,"explanation":"Add the parallel sides, multiply by height and divide by 2.","hint":"Add the parallel sides, multiply by height and divide by 2."},{"prompt":"Parallel sides are 6 cm and 10 cm, height 4 cm. Find the trapezium area in cm².","choices":["35","33","34","32"],"correct":3,"explanation":"Add the parallel sides, multiply by height and divide by 2.","hint":"Add the parallel sides, multiply by height and divide by 2."},{"prompt":"Parallel sides are 7 cm and 11 cm, height 4 cm. Find the trapezium area in cm².","choices":["36","37","38","39"],"correct":0,"explanation":"Add the parallel sides, multiply by height and divide by 2.","hint":"Add the parallel sides, multiply by height and divide by 2."},{"prompt":"Parallel sides are 8 cm and 12 cm, height 4 cm. Find the trapezium area in cm².","choices":["41","40","42","43"],"correct":1,"explanation":"Add the parallel sides, multiply by height and divide by 2.","hint":"Add the parallel sides, multiply by height and divide by 2."},{"prompt":"Parallel sides are 9 cm and 13 cm, height 4 cm. Find the trapezium area in cm².","choices":["46","45","44","47"],"correct":2,"explanation":"A