INSERT INTO public.oh2_content(id,kind,data) VALUES('math-8-scale-drawings','math','{"title":"Scale drawings","year":8,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A map uses 1 cm to represent 2 km. What distance in km is represented by 4 cm?","choices":["8","9","10","11"],"correct":0,"explanation":"Multiply the map length by the scale.","hint":"Multiply the map length by the scale."},{"prompt":"A map uses 1 cm to represent 2 km. What distance in km is represented by 5 cm?","choices":["11","10","12","13"],"correct":1,"explanation":"Multiply the map length by the scale.","hint":"Multiply the map length by the scale."},{"prompt":"A map uses 1 cm to represent 2 km. What distance in km is represented by 6 cm?","choices":["14","13","12","15"],"correct":2,"explanation":"Multiply the map length by the scale.","hint":"Multiply the map length by the scale."},{"prompt":"A map uses 1 cm to represent 2 km. What distance in km is represented by 7 cm?","choices":["17","15","16","14"],"correct":3,"explanation":"Multiply the map length by the scale.","hint":"Multiply the map length by the scale."},{"prompt":"A map uses 1 cm to represent 2 km. What distance in km is represented by 8 cm?","choices":["16","17","18","19"],"correct":0,"explanation":"Multiply the map length by the scale.","hint":"Multiply the map length by the scale."},{"prompt":"A map uses 1 cm to represent 2 km. What distance in km is represented by 9 cm?","choices":["19","18","20","21"],"correct":1,"explanation":"Multiply the map length by the scale.","hint":"Multiply the map length by the scale."},{"prompt":"A map uses 1 cm to represent 2 km. What distance in km is represented by 10 cm?","choices":["22","21","20","23"],"correct":2,"explanation":"Multiply the map length by the scale.","hint":"Multiply the map length by the scale."},{"prompt":"A map uses 1 cm to represent 2 km. What distance in km is represented by 11 cm?","choices":["25","23","24","22"],"correct":3,"explanation":"Multiply the map length by the s