INSERT INTO public.oh2_content(id,kind,data) VALUES('math-9-compound-growth','math','{"title":"Compound growth","year":9,"boards":["AQA","Edexcel"],"questions":[{"prompt":"£100 grows by 10% per year for two years. Find the final amount in pounds.","choices":["121","122","123","124"],"correct":0,"explanation":"Multiply twice by 1.1.","hint":"Multiply twice by 1.1."},{"prompt":"£200 grows by 10% per year for two years. Find the final amount in pounds.","choices":["243","242","244","245"],"correct":1,"explanation":"Multiply twice by 1.1.","hint":"Multiply twice by 1.1."},{"prompt":"£300 grows by 10% per year for two years. Find the final amount in pounds.","choices":["365","364","363","366"],"correct":2,"explanation":"Multiply twice by 1.1.","hint":"Multiply twice by 1.1."},{"prompt":"£400 grows by 10% per year for two years. Find the final amount in pounds.","choices":["487","485","486","484"],"correct":3,"explanation":"Multiply twice by 1.1.","hint":"Multiply twice by 1.1."},{"prompt":"£500 grows by 10% per year for two years. Find the final amount in pounds.","choices":["605","606","607","608"],"correct":0,"explanation":"Multiply twice by 1.1.","hint":"Multiply twice by 1.1."},{"prompt":"£600 grows by 10% per year for two years. Find the final amount in pounds.","choices":["727","726","728","729"],"correct":1,"explanation":"Multiply twice by 1.1.","hint":"Multiply twice by 1.1."},{"prompt":"£700 grows by 10% per year for two years. Find the final amount in pounds.","choices":["849","848","847","850"],"correct":2,"explanation":"Multiply twice by 1.1.","hint":"Multiply twice by 1.1."},{"prompt":"£800 grows by 10% per year for two years. Find the final amount in pounds.","choices":["971","969","970","968"],"correct":3,"explanation":"Multiply twice by 1.1.","hint":"Multiply twice by 1.1."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-9-density','math','{"title":"Density","year":9,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Mass is 24 g and volume is 6 cm³. Find density in g/cm³.","choices":["4","5","6","7"],"correct":0,"explanation":"Density is mass divided by volume.","hint":"Density is mass divided by volume."},{"prompt":"Mass is 48 g and volume is 6 cm³. Find density in g/cm³.","choices":["9","8","10","11"],"correct":1,"explanation":"Density is mass divided by volume.","hint":"Density is mass divided by volume."},{"prompt":"Mass is 72 g and volume is 6 cm³. Find density in g/cm³.","choices":["14","13","12","15"],"correct":2,"explanation":"Density is mass divided by volume.","hint":"Density is mass divided by volume."},{"prompt":"Mass is 96 g and volume is 6 cm³. Find density in g/cm³.","choices":["19","17","18","16"],"correct":3,"explanation":"Density is mass divided by volume.","hint":"Density is mass divided by volume."},{"prompt":"Mass is 120 g and volume is 6 cm³. Find density in g/cm³.","choices":["20","21","22","23"],"correct":0,"explanation":"Density is mass divided by volume.","hint":"Density is mass divided by volume."},{"prompt":"Mass is 144 g and volume is 6 cm³. Find density in g/cm³.","choices":["25","24","26","27"],"correct":1,"explanation":"Density is mass divided by volume.","hint":"Density is mass divided by volume."},{"prompt":"Mass is 168 g and volume is 6 cm³. Find density in g/cm³.","choices":["30","29","28","31"],"correct":2,"explanation":"Density is mass divided by volume.","hint":"Density is mass divided by volume."},{"prompt":"Mass is 192 g and volume is 6 cm³. Find density in g/cm³.","choices":["35","33","34","32"],"correct":3,"explanation":"Density is mass divided by volume.","hint":"Density is mass divided by volume."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-9-pressure','math','{"title":"Pressure","year":9,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Force is 30 N and area is 5 m². Find pressure in N/m².","choices":["6","7","8","9"],"correct":0,"explanation":"Pressure is force divided by area.","hint":"Pressure is force divided by area."},{"prompt":"Force is 60 N and area is 5 m². Find pressure in N/m².","choices":["13","12","14","15"],"correct":1,"explanation":"Pressure is force divided by area.","hint":"Pressure is force divided by area."},{"prompt":"Force is 90 N and area is 5 m². Find pressure in N/m².","choices":["20","19","18","21"],"correct":2,"explanation":"Pressure is force divided by area.","hint":"Pressure is force divided by area."},{"prompt":"Force is 120 N and area is 5 m². Find pressure in N/m².","choices":["27","25","26","24"],"correct":3,"explanation":"Pressure is force divided by area.","hint":"Pressure is force divided by area."},{"prompt":"Force is 150 N and area is 5 m². Find pressure in N/m².","choices":["30","31","32","33"],"correct":0,"explanation":"Pressure is force divided by area.","hint":"Pressure is force divided by area."},{"prompt":"Force is 180 N and area is 5 m². Find pressure in N/m².","choices":["37","36","38","39"],"correct":1,"explanation":"Pressure is force divided by area.","hint":"Pressure is force divided by area."},{"prompt":"Force is 210 N and area is 5 m². Find pressure in N/m².","choices":["44","43","42","45"],"correct":2,"explanation":"Pressure is force divided by area.","hint":"Pressure is force divided by area."},{"prompt":"Force is 240 N and area is 5 m². Find pressure in N/m².","choices":["51","49","50","48"],"correct":3,"explanation":"Pressure is force divided by area.","hint":"Pressure is force divided by area."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-9-arithmetic-sequence-difference','math','{"title":"Arithmetic sequence difference","year":9,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Find the common difference: 1, 8, 15, 22.","choices":["7","8","9","10"],"correct":0,"explanation":"Subtract one term from the following term.","hint":"Subtract one term from the following term."},{"prompt":"Find the common difference: 2, 9, 16, 23.","choices":["8","7","9","10"],"correct":1,"explanation":"Subtract one term from the following term.","hint":"Subtract one term from the following term."},{"prompt":"Find the common difference: 3, 10, 17, 24.","choices":["9","8","7","10"],"correct":2,"explanation":"Subtract one term from the following term.","hint":"Subtract one term from the following term."},{"prompt":"Find the common difference: 4, 11, 18, 25.","choices":["10","8","9","7"],"correct":3,"explanation":"Subtract one term from the following term.","hint":"Subtract one term from the following term."},{"prompt":"Find the common difference: 5, 12, 19, 26.","choices":["7","8","9","10"],"correct":0,"explanation":"Subtract one term from the following term.","hint":"Subtract one term from the following term."},{"prompt":"Find the common difference: 6, 13, 20, 27.","choices":["8","7","9","10"],"correct":1,"explanation":"Subtract one term from the following term.","hint":"Subtract one term from the following term."},{"prompt":"Find the common difference: 7, 14, 21, 28.","choices":["9","8","7","10"],"correct":2,"explanation":"Subtract one term from the following term.","hint":"Subtract one term from the following term."},{"prompt":"Find the common difference: 8, 15, 22, 29.","choices":["10","8","9","7"],"correct":3,"explanation":"Subtract one term from the following term.","hint":"Subtract one term from the following term."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-9-nth-term-substitution','math','{"title":"Nth term substitution","year":9,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A sequence has nth term 3n − 2. Find term 5.","choices":["13","14","15","16"],"correct":0,"explanation":"Substitute the term number for n.","hint":"Substitute the term number for n."},{"prompt":"A sequence has nth term 3n − 2. Find term 6.","choices":["17","16","18","19"],"correct":1,"explanation":"Substitute the term number for n.","hint":"Substitute the term number for n."},{"prompt":"A sequence has nth term 3n − 2. Find term 7.","choices":["21","20","19","22"],"correct":2,"explanation":"Substitute the term number for n.","hint":"Substitute the term number for n."},{"prompt":"A sequence has nth term 3n − 2. Find term 8.","choices":["25","23","24","22"],"correct":3,"explanation":"Substitute the term number for n.","hint":"Substitute the term number for n."},{"prompt":"A sequence has nth term 3n − 2. Find term 9.","choices":["25","26","27","28"],"correct":0,"explanation":"Substitute the term number for n.","hint":"Substitute the term number for n."},{"prompt":"A sequence has nth term 3n − 2. Find term 10.","choices":["29","28","30","31"],"correct":1,"explanation":"Substitute the term number for n.","hint":"Substitute the term number for n."},{"prompt":"A sequence has nth term 3n − 2. Find term 11.","choices":["33","32","31","34"],"correct":2,"explanation":"Substitute the term number for n.","hint":"Substitute the term number for n."},{"prompt":"A sequence has nth term 3n − 2. Find term 12.","choices":["37","35","36","34"],"correct":3,"explanation":"Substitute the term number for n.","hint":"Substitute the term number for n."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-9-linear-graph-intercept','math','{"title":"Linear graph intercept","year":9,"boards":["AQA","Edexcel"],"questions":[{"prompt":"For y = 4x + 3, find the y-intercept.","choices":["3","4","5","6"],"correct":0,"explanation":"At the y-axis, x is zero.","hint":"At the y-axis, x is zero."},{"prompt":"For y = 4x + 4, find the y-intercept.","choices":["5","4","6","7"],"correct":1,"explanation":"At the y-axis, x is zero.","hint":"At the y-axis, x is zero."},{"prompt":"For y = 4x + 5, find the y-intercept.","choices":["7","6","5","8"],"correct":2,"explanation":"At the y-axis, x is zero.","hint":"At the y-axis, x is zero."},{"prompt":"For y = 4x + 6, find the y-intercept.","choices":["9","7","8","6"],"correct":3,"explanation":"At the y-axis, x is zero.","hint":"At the y-axis, x is zero."},{"prompt":"For y = 4x + 7, find the y-intercept.","choices":["7","8","9","10"],"correct":0,"explanation":"At the y-axis, x is zero.","hint":"At the y-axis, x is zero."},{"prompt":"For y = 4x + 8, find the y-intercept.","choices":["9","8","10","11"],"correct":1,"explanation":"At the y-axis, x is zero.","hint":"At the y-axis, x is zero."},{"prompt":"For y = 4x + 9, find the y-intercept.","choices":["11","10","9","12"],"correct":2,"explanation":"At the y-axis, x is zero.","hint":"At the y-axis, x is zero."},{"prompt":"For y = 4x + 10, find the y-intercept.","choices":["13","11","12","10"],"correct":3,"explanation":"At the y-axis, x is zero.","hint":"At the y-axis, x is zero."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-9-gradient-from-coordinates','math','{"title":"Gradient from coordinates","year":9,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Find the gradient between (0, 2) and (3, 5).","choices":["1","2","3","4"],"correct":0,"explanation":"Divide change in y by change in x.","hint":"Divide change in y by change in x."},{"prompt":"Find the gradient between (0, 2) and (3, 8).","choices":["3","2","4","5"],"correct":1,"explanation":"Divide change in y by change in x.","hint":"Divide change in y by change in x."},{"prompt":"Find the gradient between (0, 2) and (3, 11).","choices":["5","4","3","6"],"correct":2,"explanation":"Divide change in y by change in x.","hint":"Divide change in y by change in x."},{"prompt":"Find the gradient between (0, 2) and (3, 14).","choices":["7","5","6","4"],"correct":3,"explanation":"Divide change in y by change in x.","hint":"Divide change in y by change in x."},{"prompt":"Find the gradient between (0, 2) and (3, 17).","choices":["5","6","7","8"],"correct":0,"explanation":"Divide change in y by change in x.","hint":"Divide change in y by change in x."},{"prompt":"Find the gradient between (0, 2) and (3, 20).","choices":["7","6","8","9"],"correct":1,"explanation":"Divide change in y by change in x.","hint":"Divide change in y by change in x."},{"prompt":"Find the gradient between (0, 2) and (3, 23).","choices":["9","8","7","10"],"correct":2,"explanation":"Divide change in y by change in x.","hint":"Divide change in y by change in x."},{"prompt":"Find the gradient between (0, 2) and (3, 26).","choices":["11","9","10","8"],"correct":3,"explanation":"Divide change in y by change in x.","hint":"Divide change in y by change in x."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
