INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-circle-circumference','math','{"title":"Circle circumference","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A circle has radius 3 cm. Its circumference is kπ cm. Find k.","choices":["6","7","8","9"],"correct":0,"explanation":"Circumference is 2πr.","hint":"Circumference is 2πr."},{"prompt":"A circle has radius 4 cm. Its circumference is kπ cm. Find k.","choices":["9","8","10","11"],"correct":1,"explanation":"Circumference is 2πr.","hint":"Circumference is 2πr."},{"prompt":"A circle has radius 5 cm. Its circumference is kπ cm. Find k.","choices":["12","11","10","13"],"correct":2,"explanation":"Circumference is 2πr.","hint":"Circumference is 2πr."},{"prompt":"A circle has radius 6 cm. Its circumference is kπ cm. Find k.","choices":["15","13","14","12"],"correct":3,"explanation":"Circumference is 2πr.","hint":"Circumference is 2πr."},{"prompt":"A circle has radius 7 cm. Its circumference is kπ cm. Find k.","choices":["14","15","16","17"],"correct":0,"explanation":"Circumference is 2πr.","hint":"Circumference is 2πr."},{"prompt":"A circle has radius 8 cm. Its circumference is kπ cm. Find k.","choices":["17","16","18","19"],"correct":1,"explanation":"Circumference is 2πr.","hint":"Circumference is 2πr."},{"prompt":"A circle has radius 9 cm. Its circumference is kπ cm. Find k.","choices":["20","19","18","21"],"correct":2,"explanation":"Circumference is 2πr.","hint":"Circumference is 2πr."},{"prompt":"A circle has radius 10 cm. Its circumference is kπ cm. Find k.","choices":["23","21","22","20"],"correct":3,"explanation":"Circumference is 2πr.","hint":"Circumference is 2πr."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-circle-area','math','{"title":"Circle area","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A circle has radius 3 cm. Its area is kπ cm². Find k.","choices":["9","10","11","12"],"correct":0,"explanation":"Area is πr².","hint":"Area is πr²."},{"prompt":"A circle has radius 4 cm. Its area is kπ cm². Find k.","choices":["17","16","18","19"],"correct":1,"explanation":"Area is πr².","hint":"Area is πr²."},{"prompt":"A circle has radius 5 cm. Its area is kπ cm². Find k.","choices":["27","26","25","28"],"correct":2,"explanation":"Area is πr².","hint":"Area is πr²."},{"prompt":"A circle has radius 6 cm. Its area is kπ cm². Find k.","choices":["39","37","38","36"],"correct":3,"explanation":"Area is πr².","hint":"Area is πr²."},{"prompt":"A circle has radius 7 cm. Its area is kπ cm². Find k.","choices":["49","50","51","52"],"correct":0,"explanation":"Area is πr².","hint":"Area is πr²."},{"prompt":"A circle has radius 8 cm. Its area is kπ cm². Find k.","choices":["65","64","66","67"],"correct":1,"explanation":"Area is πr².","hint":"Area is πr²."},{"prompt":"A circle has radius 9 cm. Its area is kπ cm². Find k.","choices":["83","82","81","84"],"correct":2,"explanation":"Area is πr².","hint":"Area is πr²."},{"prompt":"A circle has radius 10 cm. Its area is kπ cm². Find k.","choices":["103","101","102","100"],"correct":3,"explanation":"Area is πr².","hint":"Area is πr²."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
