INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-prism-volume','math','{"title":"Prism volume","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A prism has cross-sectional area 5 cm² and length 6 cm. Find its volume in cm³.","choices":["30","31","32","33"],"correct":0,"explanation":"Multiply cross-sectional area by length.","hint":"Multiply cross-sectional area by length."},{"prompt":"A prism has cross-sectional area 6 cm² and length 6 cm. Find its volume in cm³.","choices":["37","36","38","39"],"correct":1,"explanation":"Multiply cross-sectional area by length.","hint":"Multiply cross-sectional area by length."},{"prompt":"A prism has cross-sectional area 7 cm² and length 6 cm. Find its volume in cm³.","choices":["44","43","42","45"],"correct":2,"explanation":"Multiply cross-sectional area by length.","hint":"Multiply cross-sectional area by length."},{"prompt":"A prism has cross-sectional area 8 cm² and length 6 cm. Find its volume in cm³.","choices":["51","49","50","48"],"correct":3,"explanation":"Multiply cross-sectional area by length.","hint":"Multiply cross-sectional area by length."},{"prompt":"A prism has cross-sectional area 9 cm² and length 6 cm. Find its volume in cm³.","choices":["54","55","56","57"],"correct":0,"explanation":"Multiply cross-sectional area by length.","hint":"Multiply cross-sectional area by length."},{"prompt":"A prism has cross-sectional area 10 cm² and length 6 cm. Find its volume in cm³.","choices":["61","60","62","63"],"correct":1,"explanation":"Multiply cross-sectional area by length.","hint":"Multiply cross-sectional area by length."},{"prompt":"A prism has cross-sectional area 11 cm² and length 6 cm. Find its volume in cm³.","choices":["68","67","66","69"],"correct":2,"explanation":"Multiply cross-sectional area by length.","hint":"Multiply cross-sectional area by length."},{"prompt":"A prism has cross-sectional area 12 cm² and length 6 cm. Find its volume in cm³.","choices":["75","73","74","72"],"correct":3,"explanation":"Multiply cross-sectional area by length.","hint":"Multiply cross-sectional area by length."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-cuboid-surface-area','math','{"title":"Cuboid surface area","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A cuboid has dimensions 1 cm, 2 cm and 3 cm. Find its surface area in cm².","choices":["22","23","24","25"],"correct":0,"explanation":"Add twice each pairwise face area: 2(2n + 3n + 6).","hint":"Add twice each pairwise face area: 2(2n + 3n + 6)."},{"prompt":"A cuboid has dimensions 2 cm, 2 cm and 3 cm. Find its surface area in cm².","choices":["33","32","34","35"],"correct":1,"explanation":"Add twice each pairwise face area: 2(2n + 3n + 6).","hint":"Add twice each pairwise face area: 2(2n + 3n + 6)."},{"prompt":"A cuboid has dimensions 3 cm, 2 cm and 3 cm. Find its surface area in cm².","choices":["44","43","42","45"],"correct":2,"explanation":"Add twice each pairwise face area: 2(2n + 3n + 6).","hint":"Add twice each pairwise face area: 2(2n + 3n + 6)."},{"prompt":"A cuboid has dimensions 4 cm, 2 cm and 3 cm. Find its surface area in cm².","choices":["55","53","54","52"],"correct":3,"explanation":"Add twice each pairwise face area: 2(2n + 3n + 6).","hint":"Add twice each pairwise face area: 2(2n + 3n + 6)."},{"prompt":"A cuboid has dimensions 5 cm, 2 cm and 3 cm. Find its surface area in cm².","choices":["62","63","64","65"],"correct":0,"explanation":"Add twice each pairwise face area: 2(2n + 3n + 6).","hint":"Add twice each pairwise face area: 2(2n + 3n + 6)."},{"prompt":"A cuboid has dimensions 6 cm, 2 cm and 3 cm. Find its surface area in cm².","choices":["73","72","74","75"],"correct":1,"explanation":"Add twice each pairwise face area: 2(2n + 3n + 6).","hint":"Add twice each pairwise face area: 2(2n + 3n + 6)."},{"prompt":"A cuboid has dimensions 7 cm, 2 cm and 3 cm. Find its surface area in cm².","choices":["84","83","82","85"],"correct":2,"explanation":"Add twice each pairwise face area: 2(2n + 3n + 6).","hint":"Add twice each pairwise face area: 2(2n + 3n + 6)."},{"prompt":"A cuboid has dimensions 8 cm, 2 cm and 3 cm. Find its surface area in cm².","choices":["95","93","94","92"],"correct":3,"explanation":"Add twice each pairwise face area: 2(2n + 3n + 6).","hint":"Add twice each pairwise face area: 2(2n + 3n + 6)."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-interior-polygon-angle-sums','math','{"title":"Interior polygon angle sums","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Find the sum of interior angles of a polygon with 4 sides, in degrees.","choices":["360","361","362","363"],"correct":0,"explanation":"Use (number of sides − 2) × 180°.","hint":"Use (number of sides − 2) × 180°."},{"prompt":"Find the sum of interior angles of a polygon with 5 sides, in degrees.","choices":["541","540","542","543"],"correct":1,"explanation":"Use (number of sides − 2) × 180°.","hint":"Use (number of sides − 2) × 180°."},{"prompt":"Find the sum of interior angles of a polygon with 6 sides, in degrees.","choices":["722","721","720","723"],"correct":2,"explanation":"Use (number of sides − 2) × 180°.","hint":"Use (number of sides − 2) × 180°."},{"prompt":"Find the sum of interior angles of a polygon with 7 sides, in degrees.","choices":["903","901","902","900"],"correct":3,"explanation":"Use (number of sides − 2) × 180°.","hint":"Use (number of sides − 2) × 180°."},{"prompt":"Find the sum of interior angles of a polygon with 8 sides, in degrees.","choices":["1080","1081","1082","1083"],"correct":0,"explanation":"Use (number of sides − 2) × 180°.","hint":"Use (number of sides − 2) × 180°."},{"prompt":"Find the sum of interior angles of a polygon with 9 sides, in degrees.","choices":["1261","1260","1262","1263"],"correct":1,"explanation":"Use (number of sides − 2) × 180°.","hint":"Use (number of sides − 2) × 180°."},{"prompt":"Find the sum of interior angles of a polygon with 10 sides, in degrees.","choices":["1442","1441","1440","1443"],"correct":2,"explanation":"Use (number of sides − 2) × 180°.","hint":"Use (number of sides − 2) × 180°."},{"prompt":"Find the sum of interior angles of a polygon with 11 sides, in degrees.","choices":["1623","1621","1622","1620"],"correct":3,"explanation":"Use (number of sides − 2) × 180°.","hint":"Use (number of sides − 2) × 180°."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-regular-polygon-exterior-angles','math','{"title":"Regular polygon exterior angles","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A regular polygon has 3 sides. Find an exterior angle in degrees.","choices":["120","121","122","123"],"correct":0,"explanation":"Divide 360° by the number of sides.","hint":"Divide 360° by the number of sides."},{"prompt":"A regular polygon has 4 sides. Find an exterior angle in degrees.","choices":["91","90","92","93"],"correct":1,"explanation":"Divide 360° by the number of sides.","hint":"Divide 360° by the number of sides."},{"prompt":"A regular polygon has 5 sides. Find an exterior angle in degrees.","choices":["74","73","72","75"],"correct":2,"explanation":"Divide 360° by the number of sides.","hint":"Divide 360° by the number of sides."},{"prompt":"A regular polygon has 6 sides. Find an exterior angle in degrees.","choices":["63","61","62","60"],"correct":3,"explanation":"Divide 360° by the number of sides.","hint":"Divide 360° by the number of sides."},{"prompt":"A regular polygon has 8 sides. Find an exterior angle in degrees.","choices":["45","46","47","48"],"correct":0,"explanation":"Divide 360° by the number of sides.","hint":"Divide 360° by the number of sides."},{"prompt":"A regular polygon has 9 sides. Find an exterior angle in degrees.","choices":["41","40","42","43"],"correct":1,"explanation":"Divide 360° by the number of sides.","hint":"Divide 360° by the number of sides."},{"prompt":"A regular polygon has 10 sides. Find an exterior angle in degrees.","choices":["38","37","36","39"],"correct":2,"explanation":"Divide 360° by the number of sides.","hint":"Divide 360° by the number of sides."},{"prompt":"A regular polygon has 12 sides. Find an exterior angle in degrees.","choices":["33","31","32","30"],"correct":3,"explanation":"Divide 360° by the number of sides.","hint":"Divide 360° by the number of sides."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SE