INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-probability-expected-frequency','math','{"title":"Probability expected frequency","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"An event has probability 0.25. In 20 trials, what is its expected frequency?","choices":["5","6","7","8"],"correct":0,"explanation":"Multiply the number of trials by the probability.","hint":"Multiply the number of trials by the probability."},{"prompt":"An event has probability 0.25. In 40 trials, what is its expected frequency?","choices":["11","10","12","13"],"correct":1,"explanation":"Multiply the number of trials by the probability.","hint":"Multiply the number of trials by the probability."},{"prompt":"An event has probability 0.25. In 60 trials, what is its expected frequency?","choices":["17","16","15","18"],"correct":2,"explanation":"Multiply the number of trials by the probability.","hint":"Multiply the number of trials by the probability."},{"prompt":"An event has probability 0.25. In 80 trials, what is its expected frequency?","choices":["23","21","22","20"],"correct":3,"explanation":"Multiply the number of trials by the probability.","hint":"Multiply the number of trials by the probability."},{"prompt":"An event has probability 0.25. In 100 trials, what is its expected frequency?","choices":["25","26","27","28"],"correct":0,"explanation":"Multiply the number of trials by the probability.","hint":"Multiply the number of trials by the probability."},{"prompt":"An event has probability 0.25. In 120 trials, what is its expected frequency?","choices":["31","30","32","33"],"correct":1,"explanation":"Multiply the number of trials by the probability.","hint":"Multiply the number of trials by the probability."},{"prompt":"An event has probability 0.25. In 140 trials, what is its expected frequency?","choices":["37","36","35","38"],"correct":2,"explanation":"Multiply the number of trials by the probability.","hint":"Multiply the number of trials by the probability."},{"prompt":"An event has probability 0.25. In 160 trials, what is its expected frequency?","choices":["43","41","42","40"],"correct":3,"explanation":"Multiply the number of trials by the probability.","hint":"Multiply the number of trials by the probability."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-independent-events','math','{"title":"Independent events","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A fair coin is tossed twice. What is the probability of two heads?","choices":["1/4","0","1","2"],"correct":0,"explanation":"Multiply 1/2 by 1/2.","hint":"Multiply 1/2 by 1/2."},{"prompt":"A fair coin is tossed twice. What is the probability of two heads?","choices":["0","1/4","1","2"],"correct":1,"explanation":"Multiply 1/2 by 1/2.","hint":"Multiply 1/2 by 1/2."},{"prompt":"A fair coin is tossed twice. What is the probability of two heads?","choices":["1","0","1/4","2"],"correct":2,"explanation":"Multiply 1/2 by 1/2.","hint":"Multiply 1/2 by 1/2."},{"prompt":"A fair coin is tossed twice. What is the probability of two heads?","choices":["2","0","1","1/4"],"correct":3,"explanation":"Multiply 1/2 by 1/2.","hint":"Multiply 1/2 by 1/2."},{"prompt":"A fair coin is tossed twice. What is the probability of two heads?","choices":["1/4","0","1","2"],"correct":0,"explanation":"Multiply 1/2 by 1/2.","hint":"Multiply 1/2 by 1/2."},{"prompt":"A fair coin is tossed twice. What is the probability of two heads?","choices":["0","1/4","1","2"],"correct":1,"explanation":"Multiply 1/2 by 1/2.","hint":"Multiply 1/2 by 1/2."},{"prompt":"A fair coin is tossed twice. What is the probability of two heads?","choices":["1","0","1/4","2"],"correct":2,"explanation":"Multiply 1/2 by 1/2.","hint":"Multiply 1/2 by 1/2."},{"prompt":"A fair coin is tossed twice. What is the probability of two heads?","choices":["2","0","1","1/4"],"correct":3,"explanation":"Multiply 1/2 by 1/2.","hint":"Multiply 1/2 by 1/2."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-two-way-tables','math','{"title":"Two-way tables","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"A group has 4 pupils, of whom 1 walk and the rest cycle. How many cycle?","choices":["3","4","5","6"],"correct":0,"explanation":"Subtract walkers from the total.","hint":"Subtract walkers from the total."},{"prompt":"A group has 8 pupils, of whom 2 walk and the rest cycle. How many cycle?","choices":["7","6","8","9"],"correct":1,"explanation":"Subtract walkers from the total.","hint":"Subtract walkers from the total."},{"prompt":"A group has 12 pupils, of whom 3 walk and the rest cycle. How many cycle?","choices":["11","10","9","12"],"correct":2,"explanation":"Subtract walkers from the total.","hint":"Subtract walkers from the total."},{"prompt":"A group has 16 pupils, of whom 4 walk and the rest cycle. How many cycle?","choices":["15","13","14","12"],"correct":3,"explanation":"Subtract walkers from the total.","hint":"Subtract walkers from the total."},{"prompt":"A group has 20 pupils, of whom 5 walk and the rest cycle. How many cycle?","choices":["15","16","17","18"],"correct":0,"explanation":"Subtract walkers from the total.","hint":"Subtract walkers from the total."},{"prompt":"A group has 24 pupils, of whom 6 walk and the rest cycle. How many cycle?","choices":["19","18","20","21"],"correct":1,"explanation":"Subtract walkers from the total.","hint":"Subtract walkers from the total."},{"prompt":"A group has 28 pupils, of whom 7 walk and the rest cycle. How many cycle?","choices":["23","22","21","24"],"correct":2,"explanation":"Subtract walkers from the total.","hint":"Subtract walkers from the total."},{"prompt":"A group has 32 pupils, of whom 8 walk and the rest cycle. How many cycle?","choices":["27","25","26","24"],"correct":3,"explanation":"Subtract walkers from the total.","hint":"Subtract walkers from the total."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-frequency-totals','math','{"title":"Frequency totals","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Three scores have frequencies 1, 4 and 7. How many scores are recorded?","choices":["12","13","14","15"],"correct":0,"explanation":"Add the frequencies.","hint":"Add the frequencies."},{"prompt":"Three scores have frequencies 2, 5 and 8. How many scores are recorded?","choices":["16","15","17","18"],"correct":1,"explanation":"Add the frequencies.","hint":"Add the frequencies."},{"prompt":"Three scores have frequencies 3, 6 and 9. How many scores are recorded?","choices":["20","19","18","21"],"correct":2,"explanation":"Add the frequencies.","hint":"Add the frequencies."},{"prompt":"Three scores have frequencies 4, 7 and 10. How many scores are recorded?","choices":["24","22","23","21"],"correct":3,"explanation":"Add the frequencies.","hint":"Add the frequencies."},{"prompt":"Three scores have frequencies 5, 8 and 11. How many scores are recorded?","choices":["24","25","26","27"],"correct":0,"explanation":"Add the frequencies.","hint":"Add the frequencies."},{"prompt":"Three scores have frequencies 6, 9 and 12. How many scores are recorded?","choices":["28","27","29","30"],"correct":1,"explanation":"Add the frequencies.","hint":"Add the frequencies."},{"prompt":"Three scores have frequencies 7, 10 and 13. How many scores are recorded?","choices":["32","31","30","33"],"correct":2,"explanation":"Add the frequencies.","hint":"Add the frequencies."},{"prompt":"Three scores have frequencies 8, 11 and 14. How many scores are recorded?","choices":["36","34","35","33"],"correct":3,"explanation":"Add the frequencies.","hint":"Add the frequencies."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-estimated-mean','math','{"title":"Estimated mean","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Two equal-sized groups have estimated means 5 and 9. Find the combined estimated mean.","choices":["7","8","9","10"],"correct":0,"explanation":"Equal-sized groups have equal weight, so average the two means.","hint":"Equal-sized groups have equal weight, so average the two means."},{"prompt":"Two equal-sized groups have estimated means 6 and 10. Find the combined estimated mean.","choices":["9","8","10","11"],"correct":1,"explanation":"Equal-sized groups have equal weight, so average the two means.","hint":"Equal-sized groups have equal weight, so average the two means."},{"prompt":"Two equal-sized groups have estimated means 7 and 11. Find the combined estimated mean.","choices":["11","10","9","12"],"correct":2,"explanation":"Equal-sized groups have equal weight, so average the two means.","hint":"Equal-sized groups have equal weight, so average the two means."},{"prompt":"Two equal-sized groups have estimated means 8 and 12. Find the combined estimated mean.","choices":["13","11","12","10"],"correct":3,"explanation":"Equal-sized groups have equal weight, so average the two means.","hint":"Equal-sized groups have equal weight, so average the two means."},{"prompt":"Two equal-sized groups have estimated means 9 and 13. Find the combined estimated mean.","choices":["11","12","13","14"],"correct":0,"explanation":"Equal-sized groups have equal weight, so average the two means.","hint":"Equal-sized groups have equal weight, so average the two means."},{"prompt":"Two equal-sized groups have estimated means 10 and 14. Find the combined estimated mean.","choices":["13","12","14","15"],"correct":1,"explanation":"Equal-sized groups have equal weight, so average the two means.","hint":"Equal-sized groups have equal weight, so average the two means."},{"prompt":"Two equal-sized groups have estimated means 11 and 15. Find the combined estimated mean.","choices":["15","14","13","16"],"correct":2,"explanation":"Equal-sized groups have equal weight, so average the two means.","hint":"Equal-sized groups have equal weight, so average the two means."},{"prompt":"Two equal-sized groups have estimated means 12 and 16. Find the combined estimated mean.","choices":["17","15","16","14"],"correct":3,"explanation":"Equal-sized groups have equal weight, so average the two means.","hint":"Equal-sized groups have equal weight, so average the two means."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-linear-inequalities','math','{"title":"Linear inequalities","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"The inequality x + 1 < 6 simplifies to x < k. Find k.","choices":["5","6","7","8"],"correct":0,"explanation":"Subtract the same number from both sides.","hint":"Subtract the same number from both sides."},{"prompt":"The inequality x + 2 < 7 simplifies to x < k. Find k.","choices":["6","5","7","8"],"correct":1,"explanation":"Subtract the same number from both sides.","hint":"Subtract the same number from both sides."},{"prompt":"The inequality x + 3 < 8 simplifies to x < k. Find k.","choices":["7","6","5","8"],"correct":2,"explanation":"Subtract the same number from both sides.","hint":"Subtract the same number from both sides."},{"prompt":"The inequality x + 4 < 9 simplifies to x < k. Find k.","choices":["8","6","7","5"],"correct":3,"explanation":"Subtract the same number from both sides.","hint":"Subtract the same number from both sides."},{"prompt":"The inequality x + 5 < 10 simplifies to x < k. Find k.","choices":["5","6","7","8"],"correct":0,"explanation":"Subtract the same number from both sides.","hint":"Subtract the same number from both sides."},{"prompt":"The inequality x + 6 < 11 simplifies to x < k. Find k.","choices":["6","5","7","8"],"correct":1,"explanation":"Subtract the same number from both sides.","hint":"Subtract the same number from both sides."},{"prompt":"The inequality x + 7 < 12 simplifies to x < k. Find k.","choices":["7","6","5","8"],"correct":2,"explanation":"Subtract the same number from both sides.","hint":"Subtract the same number from both sides."},{"prompt":"The inequality x + 8 < 13 simplifies to x < k. Find k.","choices":["8","6","7","5"],"correct":3,"explanation":"Subtract the same number from both sides.","hint":"Subtract the same number from both sides."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-10-rearranging-formulae','math','{"title":"Rearranging formulae","year":10,"boards":["AQA","Edexcel"],"questions":[{"prompt":"If y = 3x + 2 and y = 5, find x.","choices":["1","2","3","4"],"correct":0,"explanation":"Subtract 2 from y, then divide by 3.","hint":"Subtract 2 from y, then divide by 3."},{"prompt":"If y = 3x + 2 and y = 8, find x.","choices":["3","2","4","5"],"correct":1,"explanation":"Subtract 2 from y, then divide by 3.","hint":"Subtract 2 from y, then divide by 3."},{"prompt":"If y = 3x + 2 and y = 11, find x.","choices":["5","4","3","6"],"correct":2,"explanation":"Subtract 2 from y, then divide by 3.","hint":"Subtract 2 from y, then divide by 3."},{"prompt":"If y = 3x + 2 and y = 14, find x.","choices":["7","5","6","4"],"correct":3,"explanation":"Subtract 2 from y, then divide by 3.","hint":"Subtract 2 from y, then divide by 3."},{"prompt":"If y = 3x + 2 and y = 17, find x.","choices":["5","6","7","8"],"correct":0,"explanation":"Subtract 2 from y, then divide by 3.","hint":"Subtract 2 from y, then divide by 3."},{"prompt":"If y = 3x + 2 and y = 20, find x.","choices":["7","6","8","9"],"correct":1,"explanation":"Subtract 2 from y, then divide by 3.","hint":"Subtract 2 from y, then divide by 3."},{"prompt":"If y = 3x + 2 and y = 23, find x.","choices":["9","8","7","10"],"correct":2,"explanation":"Subtract 2 from y, then divide by 3.","hint":"Subtract 2 from y, then divide by 3."},{"prompt":"If y = 3x + 2 and y = 26, find x.","choices":["11","9","10","8"],"correct":3,"explanation":"Subtract 2 from y, then divide by 3.","hint":"Subtract 2 from y, then divide by 3."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
