INSERT INTO public.oh2_content(id,kind,data) VALUES('math-11-quadratic-roots','math','{"title":"Quadratic roots","year":11,"boards":["AQA","Edexcel"],"questions":[{"prompt":"Find the larger root of (x − 1)(x − 4) = 0.","choices":["4","5","6","7"],"correct":0,"explanation":"Either factor is zero, giving the two roots.","hint":"Either factor is zero, giving the two roots."},{"prompt":"Find the larger root of (x − 2)(x − 5) = 0.","choices":["6","5","7","8"],"correct":1,"explanation":"Either factor is zero, giving the two roots.","hint":"Either factor is zero, giving the two roots."},{"prompt":"Find the larger root of (x − 3)(x − 6) = 0.","choices":["8","7","6","9"],"correct":2,"explanation":"Either factor is zero, giving the two roots.","hint":"Either factor is zero, giving the two roots."},{"prompt":"Find the larger root of (x − 4)(x − 7) = 0.","choices":["10","8","9","7"],"correct":3,"explanation":"Either factor is zero, giving the two roots.","hint":"Either factor is zero, giving the two roots."},{"prompt":"Find the larger root of (x − 5)(x − 8) = 0.","choices":["8","9","10","11"],"correct":0,"explanation":"Either factor is zero, giving the two roots.","hint":"Either factor is zero, giving the two roots."},{"prompt":"Find the larger root of (x − 6)(x − 9) = 0.","choices":["10","9","11","12"],"correct":1,"explanation":"Either factor is zero, giving the two roots.","hint":"Either factor is zero, giving the two roots."},{"prompt":"Find the larger root of (x − 7)(x − 10) = 0.","choices":["12","11","10","13"],"correct":2,"explanation":"Either factor is zero, giving the two roots.","hint":"Either factor is zero, giving the two roots."},{"prompt":"Find the larger root of (x − 8)(x − 11) = 0.","choices":["14","12","13","11"],"correct":3,"explanation":"Either factor is zero, giving the two roots.","hint":"Either factor is zero, giving the two roots."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('math-11-difference-of-squares','math','{"title":"Difference of squares","year":11,"boards":["AQA","Edexcel"],"questions":[{"prompt":"x² − 1 = (x − 1)(x + k). Find k.","choices":["1","2","3","4"],"correct":0,"explanation":"Use a² − b² = (a − b)(a + b).","hint":"Use a² − b² = (a − b)(a + b)."},{"prompt":"x² − 4 = (x − 2)(x + k). Find k.","choices":["3","2","4","5"],"correct":1,"explanation":"Use a² − b² = (a − b)(a + b).","hint":"Use a² − b² = (a − b)(a + b)."},{"prompt":"x² − 9 = (x − 3)(x + k). Find k.","choices":["5","4","3","6"],"correct":2,"explanation":"Use a² − b² = (a − b)(a + b).","hint":"Use a² − b² = (a − b)(a + b)."},{"prompt":"x² − 16 = (x − 4)(x + k). Find k.","choices":["7","5","6","4"],"correct":3,"explanation":"Use a² − b² = (a − b)(a + b).","hint":"Use a² − b² = (a − b)(a + b)."},{"prompt":"x² − 25 = (x − 5)(x + k). Find k.","choices":["5","6","7","8"],"correct":0,"explanation":"Use a² − b² = (a − b)(a + b).","hint":"Use a² − b² = (a − b)(a + b)."},{"prompt":"x² − 36 = (x − 6)(x + k). Find k.","choices":["7","6","8","9"],"correct":1,"explanation":"Use a² − b² = (a − b)(a + b).","hint":"Use a² − b² = (a − b)(a + b)."},{"prompt":"x² − 49 = (x − 7)(x + k). Find k.","choices":["9","8","7","10"],"correct":2,"explanation":"Use a² − b² = (a − b)(a + b).","hint":"Use a² − b² = (a − b)(a + b)."},{"prompt":"x² − 64 = (x − 8)(x + k). Find k.","choices":["11","9","10","8"],"correct":3,"explanation":"Use a² − b² = (a − b)(a + b).","hint":"Use a² − b² = (a − b)(a + b)."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
