INSERT INTO public.oh2_content(id,kind,data) VALUES('reader-14-3','book','{"title":"The Unexpected Delay at Bridge Makerspace","age":"13–15","genre":"Community fiction","college":false,"author":"ONE HOME original short-reader collection","pages":["Jules arrived at Bridge Makerspace before the afternoon activity began. The room was quiet, but there was plenty to prepare. On a small table lay a checklist, ready to be used. Then the organiser explained the difficulty: a delivery was delayed on the morning of an event. Jules had expected a simple afternoon and felt uncertain. Instead of pretending to know the answer, Jules asked for a few minutes to look carefully. There was still time to understand what had happened before anyone made a decision.","The first step was to check what supplies were already available. This took longer than making a quick guess, but it gave the group something useful to work with. Jules wrote down what was known and put a question mark beside what still needed checking. A friend suggested rushing ahead. “If we get the first part wrong, we may have to do everything twice,” Jules replied. Together they compared the information. One detail mattered more than the others: a plan had to work for the people who would actually use it.","Soon the group had a possible answer. They could adapt the activity instead of cancelling it. Jules explained the idea, then asked the others what might go wrong. At first, nobody spoke. After a moment, a younger visitor raised a concern. The group listened rather than dismissing it. They changed a small part of the plan and tried it on a limited scale. The trial was not perfect, but it showed them what to improve. Jules used a checklist to keep track of the next step.","When the visitors arrived, the group put the revised plan into practice. Someone who had missed the discussion asked why they had chosen this approach. Jules explained both the problem and the reason for the decision. That explanation helped the newcomer take part without feeling left behind. During the afternoon, the team checked how things were going. They did not assume that silence meant success. They asked people directly and made another small adjustment when it was needed.","By the end of the afternoon, Bridge Makerspace felt different. The original problem had become a chance to practise being resourceful. Jules returned a checklist to the table and wrote a note for the next group: “Check, listen, try, then improve.” The organiser thanked everyone, including the visitor whose question had changed the plan. Jules was pleased, but the best part was knowing how the group had reached its answer. They had not needed one person to know everything. They had needed people who were willing to think together."],"questions":[{"prompt":"What difficulty did the group face?","choices":["two posters gave different opening times","the first design kept falling over","a delivery was delayed on the morning of an event","two groups wanted to use the same space"],"correct":2,"explanation":"The organiser explains this difficulty on page 1.","hint":"Look back at what the group actually did."},{"prompt":"What did the group decide to do?","choices":["agree a timetable that gave each group a turn","widen the base and test the design again","replace the old poster with a clear new notice","adapt the activity instead of cancelling it"],"correct":3,"explanation":"The revised solution is described on page 3.","hint":"Look back at what the group actually did."},{"prompt":"Why did the group test a small version first?","choices":["To discover problems before using the full plan","To avoid listening to visitors","To make the task last forever","To hide the decision"],"correct":0,"explanation":"The trial let the group see what to improve before everyone arrived.","hint":"Think about what the trial revealed."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('reader-14-4','book','{"title":"The Second Attempt at Bridge Makerspace","age":"13–15","genre":"Community fiction","college":false,"author":"ONE HOME original short-reader collection","pages":["Maya arrived at Bridge Makerspace before the afternoon activity began. The room was quiet, but there was plenty to prepare. On a small table lay a ruler, ready to be used. Then the organiser explained the difficulty: the first design kept falling over. Maya had expected a simple afternoon and felt uncertain. Instead of pretending to know the answer, Maya asked for a few minutes to look carefully. There was still time to understand what had happened before anyone made a decision.","The first step was to test one change at a time on a small model. This took longer than making a quick guess, but it gave the group something useful to work with. Maya wrote down what was known and put a question mark beside what still needed checking. A friend suggested rushing ahead. “If we get the first part wrong, we may have to do everything twice,” Maya replied. Together they compared the information. One detail mattered more than the others: a plan had to work for the people who would actually use it.","Soon the group had a possible answer. They could widen the base and test the design again. Maya explained the idea, then asked the others what might go wrong. At first, nobody spoke. After a moment, a younger visitor raised a concern. The group listened rather than dismissing it. They changed a small part of the plan and tried it on a limited scale. The trial was not perfect, but it showed them what to improve. Maya used a ruler to keep track of the next step.","When the visitors arrived, the group put the revised plan into practice. Someone who had missed the discussion asked why they had chosen this approach. Maya explained both the problem and the reason for the decision. That explanation helped the newcomer take part without feeling left behind. During the afternoon, the team checked how things were going. They did not assume that silence meant success. They asked people directly and made another small adjustment when it was needed.","By the end of the afternoon, Bridge Makerspace felt different. The original problem had become a chance to practise being patient. Maya returned a ruler to the table and wrote a note for the next group: “Check, listen, try, then improve.” The organiser thanked everyone, including the visitor whose question had changed the plan. Maya was pleased, but the best part was knowing how the group had reached its answer. They had not needed one person to know everything. They had needed people who were willing to think together."],"questions":[{"prompt":"What difficulty did the group face?","choices":["new visitors found the entrance difficult to locate","two posters gave different opening times","two groups wanted to use the same space","the first design kept falling over"],"correct":3,"explanation":"The organiser explains this difficulty on page 1.","hint":"Look back at what the group actually did."},{"prompt":"What did the group decide to do?","choices":["widen the base and test the design again","replace the old poster with a clear new notice","agree a timetable that gave each group a turn","add simple signs at the confusing turning points"],"correct":0,"explanation":"The revised solution is described on page 3.","hint":"Look back at what the group actually did."},{"prompt":"Why did the group test a small version first?","choices":["To discover problems before using the full plan","To avoid listening to visitors","To make the task last forever","To hide the decision"],"correct":0,"explanation":"The trial let the group see what to improve before everyone arrived.","hint":"Think about what the trial revealed."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('reader-14-5','book','{"title":"The Quiet Question at Bridge Makerspace","age":"13–15","genre":"Community fiction","college":false,"author":"ONE HOME original short-reader collection","pages":["Ellis arrived at Bridge Makerspace before the afternoon activity began. The room was quiet, but there was plenty to prepare. On a small table lay a pencil, ready to be used. Then the organiser explained the difficulty: two posters gave different opening times. Ellis had expected a simple afternoon and felt uncertain. Instead of pretending to know the answer, Ellis asked for a few minutes to look carefully. There was still time to understand what had happened before anyone made a decision.","The first step was to check the date and ask the organiser which notice was current. This took longer than making a quick guess, but it gave the group something useful to work with. Ellis wrote down what was known and put a question mark beside what still needed checking. A friend suggested rushing ahead. “If we get the first part wrong, we may have to do everything twice,” Ellis replied. Together they compared the information. One detail mattered more than the others: a plan had to work for the people who would actually use it.","Soon the group had a possible answer. They could replace the old poster with a clear new notice. Ellis explained the idea, then asked the others what might go wrong. At first, nobody spoke. After a moment, a younger visitor raised a concern. The group listened rather than dismissing it. They changed a small part of the plan and tried it on a limited scale. The trial was not perfect, but it showed them what to improve. Ellis used a pencil to keep track of the next step.","When the visitors arrived, the group put the revised plan into practice. Someone who had missed the discussion asked why they had chosen this approach. Ellis explained both the problem and the reason for the decision. That explanation helped the newcomer take part without feeling left behind. During the afternoon, the team checked how things were going. They did not assume that silence meant success. They asked people directly and made another small adjustment when it was needed.","By the end of the afternoon, Bridge Makerspace felt different. The original problem had become a chance to practise being thoughtful. Ellis returned a pencil to the table and wrote a note for the next group: “Check, listen, try, then improve.” The organiser thanked everyone, including the visitor whose question had changed the plan. Ellis was pleased, but the best part was knowing how the group had reached its answer. They had not needed one person to know everything. They had needed people who were willing to think together."],"questions":[{"prompt":"What difficulty did the group face?","choices":["two posters gave different opening times","two groups wanted to use the same space","new visitors found the entrance difficult to locate","a box of donated objects had lost its labels"],"correct":0,"explanation":"The organiser explains this difficulty on page 1.","hint":"Look back at what the group actually did."},{"prompt":"What did the group decide to do?","choices":["agree a timetable that gave each group a turn","replace the old poster with a clear new notice","add simple signs at the confusing turning points","write labels that explained where each object came from"],"correct":1,"explanation":"The revised solution is described on page 3.","hint":"Look back at what the group actually did."},{"prompt":"Why did the group test a small version first?","choices":["To discover problems before using the full plan","To avoid listening to visitors","To make the task last forever","To hide the decision"],"correct":0,"explanation":"The trial let the group see what to improve before everyone arrived.","hint":"Think about what the trial revealed."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('reader-14-6','book','{"title":"The Shared Decision at Bridge Makerspace","age":"13–15","genre":"Community fiction","college":false,"author":"ONE HOME original short-reader collection","pages":["Asha arrived at Bridge Makerspace before the afternoon activity began. The room was quiet, but there was plenty to prepare. On a small table lay a folder, ready to be used. Then the organiser explained the difficulty: two groups wanted to use the same space. Asha had expected a simple afternoon and felt uncertain. Instead of pretending to know the answer, Asha asked for a few minutes to look carefully. There was still time to understand what had happened before anyone made a decision.","The first step was to listen to both groups and look at the booking sheet. This took longer than making a quick guess, but it gave the group something useful to work with. Asha wrote down what was known and put a question mark beside what still needed checking. A friend suggested rushing ahead. “If we get the first part wrong, we may have to do everything twice,” Asha replied. Together they compared the information. One detail mattered more than the others: a plan had to work for the people who would actually use it.","Soon the group had a possible answer. They could agree a timetable that gave each group a turn. Asha explained the idea, then asked the others what might go wrong. At first, nobody spoke. After a moment, a younger visitor raised a concern. The group listened rather than dismissing it. They changed a small part of the plan and tried it on a limited scale. The trial was not perfect, but it showed them what to improve. Asha used a folder to keep track of the next step.","When the visitors arrived, the group put the revised plan into practice. Someone who had missed the discussion asked why they had chosen this approach. Asha explained both the problem and the reason for the decision. That explanation helped the newcomer take part without feeling left behind. During the afternoon, the team checked how things were going. They did not assume that silence meant success. They asked people directly and made another small adjustment when it was needed.","By the end of the afternoon, Bridge Makerspace felt different. The original problem had become a chance to practise being fair. Asha returned a folder to the table and wrote a note for the next group: “Check, listen, try, then improve.” The organiser thanked everyone, including the visitor whose question had changed the plan. Asha was pleased, but the best part was knowing how the group had reached its answer. They had not needed one person to know everything. They had needed people who were willing to think together."],"questions":[{"prompt":"What difficulty did the group face?","choices":["new visitors found the entrance difficult to locate","two groups wanted to use the same space","a box of donated objects had lost its labels","the planned activity left quieter visitors with no way to join"],"correct":1,"explanation":"The organiser explains this difficulty on page 1.","hint":"Look back at what the group actually did."},{"prompt":"What did the group decide to do?","choices":["write labels that explained where each object came from","add simple signs at the confusing turning points","agree a timetable that gave each group a turn","invite people to choose how they wanted to take part"],"correct":2,"explanation":"The revised solution is described on page 3.","hint":"Look back at what the group actually did."},{"prompt":"Why did the group test a small version first?","choices":["To discover problems before using the full plan","To avoid listening to visitors","To make the task last forever","To hide the decision"],"correct":0,"explanation":"The trial let the group see what to improve before everyone arrived.","hint":"Think about what the trial revealed."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('reader-14-7','book','{"title":"A Better Route at Bridge Makerspace","age":"13–15","genre":"Community fiction","college":false,"author":"ONE HOME original short-reader collection","pages":["Robin arrived at Bridge Makerspace before the afternoon activity began. The room was quiet, but there was plenty to prepare. On a small table lay a map, ready to be used. Then the organiser explained the difficulty: new visitors found the entrance difficult to locate. Robin had expected a simple afternoon and felt uncertain. Instead of pretending to know the answer, Robin asked for a few minutes to look carefully. There was still time to understand what had happened before anyone made a decision.","The first step was to walk the route with a first-time visitor. This took longer than making a quick guess, but it gave the group something useful to work with. Robin wrote down what was known and put a question mark beside what still needed checking. A friend suggested rushing ahead. “If we get the first part wrong, we may have to do everything twice,” Robin replied. Together they compared the information. One detail mattered more than the others: a plan had to work for the people who would actually use it.","Soon the group had a possible answer. They could add simple signs at the confusing turning points. Robin explained the idea, then asked the others what might go wrong. At first, nobody spoke. After a moment, a younger visitor raised a concern. The group listened rather than dismissing it. They changed a small part of the plan and tried it on a limited scale. The trial was not perfect, but it showed them what to improve. Robin used a map to keep track of the next step.","When the visitors arrived, the group put the revised plan into practice. Someone who had missed the discussion asked why they had chosen this approach. Robin explained both the problem and the reason for the decision. That explanation helped the newcomer take part without feeling left behind. During the afternoon, the team checked how things were going. They did not assume that silence meant success. They asked people directly and made another small adjustment when it was needed.","By the end of the afternoon, Bridge Makerspace felt different. The original problem had become a chance to practise being observant. Robin returned a map to the table and wrote a note for the next group: “Check, listen, try, then improve.” The organiser thanked everyone, including the visitor whose question had changed the plan. Robin was pleased, but the best part was knowing how the group had reached its answer. They had not needed one person to know everything. They had needed people who were willing to think together."],"questions":[{"prompt":"What difficulty did the group face?","choices":["the planned activity left quieter visitors with no way to join","a box of donated objects had lost its labels","new visitors found the entrance difficult to locate","a delivery was delayed on the morning of an event"],"correct":2,"explanation":"The organiser explains this difficulty on page 1.","hint":"Look back at what the group actually did."},{"prompt":"What did the group decide to do?","choices":["adapt the activity instead of cancelling it","write labels that explained where each object came from","invite people to choose how they wanted to take part","add simple signs at the confusing turning points"],"correct":3,"explanation":"The revised solution is described on page 3.","hint":"Look back at what the group actually did."},{"prompt":"Why did the group test a small version first?","choices":["To discover problems before using the full plan","To avoid listening to visitors","To make the task last forever","To hide the decision"],"correct":0,"explanation":"The trial let the group see what to improve before everyone arrived.","hint":"Think about what the trial revealed."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('reader-15-1','book','{"title":"The Missing Label at Lighthouse Reading Room","age":"15–16","genre":"Community fiction","college":false,"author":"ONE HOME original short-reader collection","pages":["Amira arrived at Lighthouse Reading Room before the afternoon activity began. The room was quiet, but there was plenty to prepare. On a small table lay a notebook, ready to be used. Then the organiser explained the difficulty: a box of donated objects had lost its labels. Amira had expected a simple afternoon and felt uncertain. Instead of pretending to know the answer, Amira asked for a few minutes to look carefully. There was still time to understand what had happened before anyone made a decision.","The first step was to ask the donors for their notes. This took longer than making a quick guess, but it gave the group something useful to work with. Amira wrote down what was known and put a question mark beside what still needed checking. A friend suggested rushing ahead. “If we get the first part wrong, we may have to do everything twice,” Amira replied. Together they compared the information. One detail mattered more than the others: a plan had to work for the people who would actually use it.","Soon the group had a possible answer. They could write labels that explained where each object came from. Amira explained the idea, then asked the others what might go wrong. At first, nobody spoke. After a moment, a younger visitor raised a concern. The group listened rather than dismissing it. They changed a small part of the plan and tried it on a limited scale. The trial was not perfect, but it showed them what to improve. Amira used a notebook to keep track of the next step.","When the visitors arrived, the group put the revised plan into practice. Someone who had missed the discussion asked why they had chosen this approach. Amira explained both the problem and the reason for the decision. That explanation helped the newcomer take part without feeling left behind. During the afternoon, the team checked how things were going. They did not assume that silence meant success. They asked people directly and made another small adjustment when it was needed.","By the end of the afternoon, Lighthouse Reading Room felt different. The original problem had become a chance to practise being careful. Amira returned a notebook to the table and wrote a note for the next group: “Check, listen, try, then improve.” The organiser thanked everyone, including the visitor whose question had changed the plan. Amira was pleased, but the best part was knowing how the group had reached its answer. They had not needed one person to know everything. They had needed people who were willing to think together."],"questions":[{"prompt":"What difficulty did the group face?","choices":["a box of donated objects had lost its labels","the planned activity left quieter visitors with no way to join","a delivery was delayed on the morning of an event","the first design kept falling over"],"correct":0,"explanation":"The organiser explains this difficulty on page 1.","hint":"Look back at what the group actually did."},{"prompt":"What did the group decide to do?","choices":["invite people to choose how they wanted to take part","write labels that explained where each object came from","adapt the activity instead of cancelling it","widen the base and test the design again"],"correct":1,"explanation":"The revised solution is described on page 3.","hint":"Look back at what the group actually did."},{"prompt":"Why did the group test a small version first?","choices":["To discover problems before using the full plan","To avoid listening to visitors","To make the task last forever","To hide the decision"],"correct":0,"explanation":"The trial let the group see what to improve before everyone arrived.","hint":"Think about what the trial revealed."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
INSERT INTO public.oh2_content(id,kind,data) VALUES('reader-15-2','book','{"title":"A Place for Everyone at Lighthouse Reading Room","age":"15–16","genre":"Community fiction","college":false,"author":"ONE HOME original short-reader collection","pages":["Noah arrived at Lighthouse Reading Room before the afternoon activity began. The room was quiet, but there was plenty to prepare. On a small table lay a sketchbook, ready to be used. Then the organiser explained the difficulty: the planned activity left quieter visitors with no way to join. Noah had expected a simple afternoon and felt uncertain. Instead of pretending to know the answer, Noah asked for a few minutes to look carefully. There was still time to understand what had happened before anyone made a decision.","The first step was to offer a drawing table as well as a spoken discussion. This took longer than making a quick guess, but it gave the group something useful to work with. Noah wrote down what was known and put a question mark beside what still needed checking. A friend suggested rushing ahead. “If we get the first part wrong, we may have to do everything twice,” Noah replied. Together they compared the information. One detail mattered more than the others: a plan had to work for the people who would actually use it.","Soon the group had a possible answer. They could invite people to choose how they wanted to take part. Noah explained the idea, then asked the others what might go wrong. At first, nobody spoke. After a moment, a younger visitor raised a concern. The group listened rather than dismissing it. They changed a small part of the plan and tried it on a limited scale. The trial was not perfect, but it showed them what to improve. Noah used a sketchbook to keep track of the next step.","When the visitors arrived, the group put the revised plan into practice. Someone who had missed the discussion asked why they had chosen this approach. Noah explained both the problem and the reason for the decision. That explanation helped the newcomer take part without feeling left behind. During the afternoon, the team checked how things were going. They did not assume that silence meant success. They asked people directly and made another small adjustment when it was needed.","By the end of the afternoon, Lighthouse Reading Room felt different. The original problem had become a chance to practise being welcoming. Noah returned a sketchbook to the table and wrote a note for the next group: “Check, listen, try, then improve.” The organiser thanked everyone, including the visitor whose question had changed the plan. Noah was pleased, but the best part was knowing how the group had reached its answer. They had not needed one person to know everything. They had needed people who were willing to think together."],"questions":[{"prompt":"What difficulty did the group face?","choices":["a delivery was delayed on the morning of an event","the planned activity left quieter visitors with no way to join","the first design kept falling over","two posters gave different opening times"],"correct":1,"explanation":"The organiser explains this difficulty on page 1.","hint":"Look back at what the group actually did."},{"prompt":"What did the group decide to do?","choices":["widen the base and test the design again","adapt the activity instead of cancelling it","invite people to choose how they wanted to take part","replace the old poster with a clear new notice"],"correct":2,"explanation":"The revised solution is described on page 3.","hint":"Look back at what the group actually did."},{"prompt":"Why did the group test a small version first?","choices":["To discover problems before using the full plan","To avoid listening to visitors","To make the task last forever","To hide the decision"],"correct":0,"explanation":"The trial let the group see what to improve before everyone arrived.","hint":"Think about what the trial revealed."}]}'::jsonb) ON CONFLICT(id) DO UPDATE SET data=excluded.data;
